-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/jeuno/Wings_of_Gold.lua"]={["Path"]="scripts/quests/jeuno/Wings_of_Gold.lua",["SHA256"]="82d7b9129f95f1317966f8e5da7defb437311833ba0a42fae10b41cc66492bd3",["Text"]="-----------------------------------\n-- Wings of Gold\n-----------------------------------\n-- Log ID: 3, Quest ID: 60\n-- Brutus : !pos -55 8 95 244\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.WINGS_OF_GOLD)\n\nquest.reward =\n{\n    item     = xi.item.BARBAROI_AXE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.PATH_OF_THE_BEASTMASTER) and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL and\n                player:getMainJob() == xi.job.BST\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(139)\n                    else\n                        return quest:progressEvent(137)\n                    end\n                end,\n\n            },\n            onEventFinish =\n            {\n                [137] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n\n                [139] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Prog', 1) -- If declined then future Brutus quest start will use short dialog\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MIDDLE_DELKFUTTS_TOWER] =\n        {\n            ['Treasure_Chest' ] =\n            {\n                onTrade = function(player, npc, trade)\n                    if not player:hasKeyItem(xi.keyItem.GUIDING_BELL) then\n                        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.GUIDING_BELL)\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.UPPER_DELKFUTTS_TOWER] =\n        {\n            ['Treasure_Chest' ] =\n            {\n                onTrade = function(player, npc, trade)\n                    if not player:hasKeyItem(xi.keyItem.GUIDING_BELL) then\n                        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.GUIDING_BELL)\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.GUIDING_BELL) then\n                        return quest:event(136)\n                    else\n                        return quest:progressEvent(138)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [138] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                        player:delKeyItem(xi.keyItem.GUIDING_BELL)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.SCATTERED_INTO_SHADOW)\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus'] = quest:event(134):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Your_Crystal_Ball.lua"]={["Path"]="scripts/quests/jeuno/Your_Crystal_Ball.lua",["SHA256"]="780f5f455d395173b351f68a1d0022e61990920f01f84065700e832f16698f2d",["Text"]="-----------------------------------\n-- Your Crystal Ball\n-----------------------------------\n-- Log ID: 3, Quest ID: 9\n-- Kurou-Morou : !pos -4 -6 -28 245\n-- Rockwell    : !pos -18 -13 181 198\n-----------------------------------\nlocal lowerJeunoID = zones[xi.zone.LOWER_JEUNO]\nlocal mazeID       = zones[xi.zone.MAZE_OF_SHAKHRAMI]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.YOUR_CRYSTAL_BALL)\n\nquest.reward =\n{\n    title    = xi.title.FORTUNE_TELLER_IN_TRAINING,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getFameLevel(xi.fameArea.JEUNO) >= 2\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Kurou-Morou'] = quest:progressEvent(194),\n\n            onEventFinish =\n            {\n                [194] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Kurou-Morou'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(191) -- Reminder\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        npcUtil.tradeMatches(trade, { { xi.item.DIVINATION_SPHERE, 1 } })\n                    then\n                        return quest:progressEvent(196)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [196] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 16)\n                        player:addFame(xi.fameArea.BASTOK, 16)\n                        player:addFame(xi.fameArea.WINDURST, 16)\n                        player:tradeComplete()\n                        player:messageText(npc, lowerJeunoID.text.FORTUNE_TOLD_BY_KUROU_MOROU, false, 6)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.MAZE_OF_SHAKHRAMI] =\n        {\n            ['Rockwell'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        if GetSystemTime() >= quest:getVar(player, 'Wait') then\n                            return quest:progressEvent(52)\n                        else\n                            return quest:messageSpecial(mazeID.text.WAIT_A_BIT_LONGER, 0, xi.item.DIVINATION_SPHERE)\n                        end\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.AHRIMAN_LENS, 1 } }) then\n                        local progress = quest:getVar(player, 'Prog')\n                        if progress == 0 then\n                            player:tradeComplete()\n                            quest:setVar(player, 'Prog', 1)\n                            quest:setVar(player, 'Wait', GetSystemTime() + 60) -- 1 minute wait time\n                            return quest:messageSpecial(mazeID.text.SUBMERGED_ITEM, xi.item.AHRIMAN_LENS)\n                        elseif progress == 1 then\n                            return quest:messageSpecial(mazeID.text.MORE_THAN_ONE, xi.item.AHRIMAN_LENS)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [52] = function(player, csid, option, npc)\n                    if player:getFreeSlotsCount() ~= 0 then\n                        quest:setVar(player, 'Prog', 2)\n                        player:addItem(xi.item.DIVINATION_SPHERE)\n                    else\n                        player:messageSpecial(mazeID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.DIVINATION_SPHERE)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/helpers.lua"]={["Path"]="scripts/quests/jeuno/helpers.lua",["SHA256"]="abe04bf31c74eacec47584f8e150ad7e632f39d4b74a707bcef0037a7f8351ea",["Text"]="-----------------------------------\n-- Helpers for Jeuno quests\n-----------------------------------\nxi = xi or {}\nxi.jeuno = xi.jeuno or {}\nxi.jeuno.helpers = xi.jeuno.helpers or {}\n\n-- Base class for use by the Gobbiebag questline to reduce redundant code.\n-- The quests differ slightly in requested items, inventory size key, text, etc.\n-- The params parameter stores the tunable information needed to perform the proper quest in the chain.\nxi.jeuno.helpers.GobbiebagQuest = {}\n\nsetmetatable(xi.jeuno.helpers.GobbiebagQuest, { __index = Quest })\nxi.jeuno.helpers.GobbiebagQuest.__index = xi.jeuno.helpers.GobbiebagQuest\n\nfunction xi.jeuno.helpers.GobbiebagQuest:new(params)\n    local quest = Quest:new(xi.questLog.JEUNO, params.questId)\n\n    quest.reward = params.reward\n\n    local bagIncrease = 5\n\n    -- If quest is available or accepted, the correct dialogue ID is the expected pre quest inventory size offset by 1\n    local getPendingDialogueId = function(player)\n        return (player:getContainerSize(xi.inv.INVENTORY) + 1)\n    end\n\n    -- If quest is completed, the correct dialogue ID is the expected post quest inventory size offset by 1\n    local getCompleteDiaglogueId = function(player)\n        return (player:getContainerSize(xi.inv.INVENTORY) + bagIncrease + 1)\n    end\n\n    local getReqsMet = function(player)\n        return  player:getFameLevel(xi.fameArea.JEUNO) >= params.fame and\n                player:getContainerSize(xi.inv.INVENTORY) == params.startInventorySize and\n                (params.prerequisite == nil or player:hasCompletedQuest(xi.questLog.JEUNO, params.prerequisite))\n    end\n\n    quest.sections =\n    {\n        {\n            check = function(player, status, vars)\n                return status == xi.questStatus.QUEST_AVAILABLE and getReqsMet(player)\n            end,\n\n            [xi.zone.LOWER_JEUNO] =\n            {\n                ['Bluffnix'] =\n                {\n                    onTrigger = function(player, npc)\n                        return quest:progressEvent(43, getPendingDialogueId(player), xi.questStatus.QUEST_AVAILABLE, getReqsMet(player) and 1 or 0)\n                    end\n                },\n\n                onEventFinish =\n                {\n                    [43] = function(player, csid, option, npc)\n                        if option == 0 then\n                            quest:begin(player)\n                        end\n                    end\n                },\n            },\n        },\n\n        {\n            check = function(player, status, vars)\n                return status == xi.questStatus.QUEST_ACCEPTED and getReqsMet(player)\n            end,\n\n            [xi.zone.LOWER_JEUNO] =\n            {\n                ['Bluffnix'] =\n                {\n                    onTrade = function(player, npc, trade)\n                        if\n                            npcUtil.tradeHasExactly(trade, params.tradeItems) or\n                            npcUtil.tradeHasExactly(trade, params.tradeStew)\n                        then\n                            return quest:progressEvent(73, getCompleteDiaglogueId(player))\n                        else\n                            return quest:progressEvent(43, getPendingDialogueId(player), xi.questStatus.QUEST_ACCEPTED, 1)\n                        end\n                    end,\n\n                    onTrigger = function(player, npc)\n                        return quest:progressEvent(43, getPendingDialogueId(player), xi.questStatus.QUEST_ACCEPTED, 1)\n                    end,\n                },\n\n                onEventFinish =\n                {\n                    [73] = function(player, csid, option, npc)\n                        if quest:complete(player) then\n                            player:changeContainerSize(xi.inv.INVENTORY, bagIncrease)\n\n                            if player:getContainerSize(xi.inv.MOGSATCHEL) > 0 then\n                                player:changeContainerSize(xi.inv.MOGSATCHEL, bagIncrease)\n                            end\n\n                            player:messageSpecial(params.message)\n                            player:confirmTrade()\n                        end\n                    end\n                },\n            },\n        },\n    }\n\n    self.__index = self\n    setmetatable(quest, self)\n    return quest\nend\n\n-- Base class for use by the Zalsuhm unlocking a myth quests to reduce redundant code.\n-- The quests differ only in job matching the weapon\nxi.jeuno.helpers.UnlockingAMyth = {}\n\nsetmetatable(xi.jeuno.helpers.UnlockingAMyth, { __index = Quest })\nxi.jeuno.helpers.UnlockingAMyth.__index = xi.jeuno.helpers.UnlockingAMyth\n\nfunction xi.jeuno.helpers.UnlockingAMyth:new(jobId)\n    -- wsId is unused, but useful data for testing/sanity\n    local vigilWeaponsData =\n    {\n        [xi.job.WAR] =\n        {\n            itemId = xi.item.STURDY_AXE, -- (WAR)\n            wsUnlockId = xi.wsUnlock.KINGS_JUSTICE,\n            wsId = xi.weaponskill.KINGS_JUSTICE,\n        },\n        [xi.job.MNK] =\n        {\n            itemId = xi.item.BURNING_FISTS, -- (MNK)\n            wsUnlockId = xi.wsUnlock.ASCETICS_FURY,\n            wsId = xi.weaponskill.ASCETICS_FURY,\n        },\n        [xi.job.WHM] =\n        {\n            itemId = xi.item.WEREBUSTER, -- (WHM)\n            wsUnlockId = xi.wsUnlock.MYSTIC_BOON,\n            wsId = xi.weaponskill.MYSTIC_BOON,\n        },\n        [xi.job.BLM] =\n        {\n            itemId = xi.item.MAGES_STAFF, -- (BLM)\n            wsUnlockId = xi.wsUnlock.VIDOHUNIR,\n            wsId = xi.weaponskill.VIDOHUNIR,\n        },\n        [xi.job.RDM] =\n        {\n            itemId = xi.item.VORPAL_SWORD, -- (RDM)\n            wsUnlockId = xi.wsUnlock.DEATH_BLOSSOM,\n            wsId = xi.weaponskill.DEATH_BLOSSOM,\n        },\n        [xi.job.THF] =\n        {\n            itemId = xi.item.SWORDBREAKER, -- (THF)\n            wsUnlockId = xi.wsUnlock.MANDALIC_STAB,\n            wsId = xi.weaponskill.MANDALIC_STAB,\n        },\n        [xi.job.PLD] =\n        {\n            itemId = xi.item.BRAVE_BLADE, -- (PLD)\n            wsUnlockId = xi.wsUnlock.ATONEMENT,\n            wsId = xi.weaponskill.ATONEMENT,\n        },\n        [xi.job.DRK] =\n        {\n            itemId = xi.item.DEATH_SICKLE, -- (DRK)\n            wsUnlockId = xi.wsUnlock.INSURGENCY,\n            wsId = xi.weaponskill.INSURGENCY,\n        },\n        [xi.job.BST] =\n        {\n            itemId = xi.item.DOUBLE_AXE, -- (BST)\n            wsUnlockId = xi.wsUnlock.PRIMAL_REND,\n            wsId = xi.weaponskill.PRIMAL_REND,\n        },\n        [xi.job.BRD] =\n        {\n            itemId = xi.item.DANCING_DAGGER, -- (BRD)\n            wsUnlockId = xi.wsUnlock.MORDANT_RIME,\n            wsId = xi.weaponskill.MORDANT_RIME,\n        },\n        [xi.job.RNG] =\n        {\n            itemId = xi.item.KILLER_BOW, -- (RNG)\n            wsUnlockId = xi.wsUnlock.TRUEFLIGHT,\n            wsId = xi.weaponskill.TRUEFLIGHT,\n        },\n        [xi.job.SAM] =\n        {\n            itemId = xi.item.WINDSLICER, -- (SAM)\n            wsUnlockId = xi.wsUnlock.TACHI_RANA,\n            wsId = xi.weaponskill.TACHI_RANA,\n        },\n        [xi.job.NIN] =\n        {\n            itemId = xi.item.SASUKE_KATANA, -- (NIN)\n            wsUnlockId = xi.wsUnlock.BLADE_KAMU,\n            wsId = xi.weaponskill.BLADE_KAMU,\n        },\n        [xi.job.DRG] =\n        {\n            itemId = xi.item.RADIANT_LANCE, -- (DRG)\n            wsUnlockId = xi.wsUnlock.DRAKESBANE,\n            wsId = xi.weaponskill.DRAKESBANE,\n        },\n        [xi.job.SMN] =\n        {\n            itemId = xi.item.SCEPTER_STAFF, -- (SMN)\n            wsUnlockId = xi.wsUnlock.GARLAND_OF_BLISS,\n            wsId = xi.weaponskill.GARLAND_OF_BLISS,\n        },\n        [xi.job.BLU] =\n        {\n            itemId = xi.item.WIGHTSLAYER, -- (BLU)\n            wsUnlockId = xi.wsUnlock.EXPIACION,\n            wsId = xi.weaponskill.EXPIACION,\n        },\n        [xi.job.COR] =\n        {\n            itemId = xi.item.QUICKSILVER, -- (COR)\n            wsUnlockId = xi.wsUnlock.LEADEN_SALUTE,\n            wsId = xi.weaponskill.LEADEN_SALUTE,\n        },\n        [xi.job.PUP] =\n        {\n            itemId = xi.item.INFERNO_CLAWS, -- (PUP)\n            wsUnlockId = xi.wsUnlock.STRINGING_PUMMEL,\n            wsId = xi.weaponskill.STRINGING_PUMMEL,\n        },\n        [xi.job.DNC] =\n        {\n            itemId = xi.item.MAIN_GAUCHE, -- (DNC)\n            wsUnlockId = xi.wsUnlock.PYRRHIC_KLEOS,\n            wsId = xi.weaponskill.PYRRHIC_KLEOS,\n        },\n        [xi.job.SCH] =\n        {\n            itemId = xi.item.ELDER_STAFF, -- (SCH)\n            wsUnlockId = xi.wsUnlock.OMNISCIENCE,\n            wsId = xi.weaponskill.OMNISCIENCE,\n        },\n    }\n\n    local questId    = xi.quest.id.jeuno.UNLOCKING_A_MYTH_WARRIOR - 1 + jobId\n    local weaponData = vigilWeaponsData[jobId]\n\n    local quest = Quest:new(xi.questLog.JEUNO, questId)\n\n    quest.sections =\n    {\n        {\n            check = function(player, status, vars)\n                -- quest can be flagged multiple times for different jobs, no need for additional check here\n                -- https://www.ffxiah.com/forum/topic/11987/cancel-unlocking-a-myth-quest\n                return player:getMainJob() == jobId and status == xi.questStatus.QUEST_AVAILABLE\n            end,\n\n            [xi.zone.LOWER_JEUNO] =\n            {\n                ['Zalsuhm'] =\n                {\n                    onTrigger = function(player, npc)\n                        -- Must be wearing one of the weapons in the primary slot to flag the quest\n                        local weaponMain      = player:getEquipID(xi.slot.MAIN)\n                        local weaponRanged    = player:getEquipID(xi.slot.RANGED)\n                        local isWearingWeapon = weaponMain == weaponData.itemId or weaponRanged == weaponData.itemId\n                        local upsetZalsuhm    = quest:getVar(player, 'Upset_Zalsuhm') > 0\n\n                        if player:needToZone() and upsetZalsuhm then\n                            return quest:progressEvent(10090)\n                        else\n                            if upsetZalsuhm then\n                                quest:setVar(player, 'Upset_Zalsuhm', 0)\n                            end\n\n                            if isWearingWeapon then\n                                return quest:progressEvent(10086, jobId)\n                            else\n                                return quest:progressEvent(10085)\n                            end\n                        end\n                    end\n                },\n\n                onEventFinish =\n                {\n                    [10086] = function(player, csid, option, npc)\n                        if option == 53 then\n                            quest:setVar(player, 'Upset_Zalsuhm', 1)\n                            player:needToZone(true)\n                        elseif option == jobId then\n                            quest:begin(player)\n                        end\n                    end,\n                },\n            },\n        },\n\n        {\n            check = function(player, status, vars)\n                return player:getMainJob() == jobId and status == xi.questStatus.QUEST_ACCEPTED\n            end,\n\n            [xi.zone.LOWER_JEUNO] =\n            {\n                ['Zalsuhm'] =\n                {\n                    onTrade = function(player, npc, trade)\n                        -- TODO is there a message for trading anything else?\n                        if npcUtil.tradeHasExactly(trade, weaponData.itemId) then\n                            local requiredWsPoints = xi.equipment.vigilWeaponRequiredWsPoints(player)\n                            local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                            if wsPoints <= requiredWsPoints / 5 then\n                                return quest:event(10091)\n                            elseif wsPoints <= requiredWsPoints * 4 / 5 then\n                                return quest:event(10092)\n                            elseif wsPoints < requiredWsPoints then\n                                return quest:event(10093)\n                            elseif wsPoints >= requiredWsPoints then\n                                return quest:progressEvent(10088, jobId)\n                            end\n                        end\n                    end,\n\n                    onTrigger = function(player, npc)\n                        return quest:cutscene(10087)\n                    end,\n                },\n\n                onEventFinish =\n                {\n                    [10088] = function(player, csid, option, npc)\n                        if quest:complete(player) then\n                            player:messageSpecial(zones[player:getZoneID()].text.MYTHIC_LEARNED, jobId)\n                            player:addLearnedWeaponskill(weaponData.wsUnlockId)\n                            -- player keeps vigil weapon\n                        end\n                    end,\n                },\n            },\n        },\n    }\n\n    self.__index = self\n    setmetatable(quest, self)\n    return quest\nend\n\n-- Base class for use by the Gobbiebag questline to reduce redundant code.\n-- The quests differ slightly in requested items, inventory size key, text, etc.\n-- The params parameter stores the tunable information needed to perform the proper quest in the chain.\nxi.jeuno.helpers.BorghertzQuests = {}\n\nsetmetatable(xi.jeuno.helpers.BorghertzQuests, { __index = Quest })\nxi.jeuno.helpers.BorghertzQuests.__index = xi.jeuno.helpers.BorghertzQuests\n\nfunction xi.jeuno.helpers.BorghertzQuests:new(params)\n    local quest = Quest:new(xi.questLog.JEUNO, params.questId)\n\n    local borghertzQuests =\n    {\n        xi.quest.id.jeuno.BORGHERTZS_WARRING_HANDS,\n        xi.quest.id.jeuno.BORGHERTZS_STRIKING_HANDS,\n        xi.quest.id.jeuno.BORGHERTZS_HEALING_HANDS,\n        xi.quest.id.jeuno.BORGHERTZS_SORCEROUS_HANDS,\n        xi.quest.id.jeuno.BORGHERTZS_VERMILLION_HANDS,\n        xi.quest.id.jeuno.BORGHERTZS_SNEAKY_HANDS,\n        xi.quest.id.jeuno.BORGHERTZS_STALWART_HANDS,\n        xi.quest.id.jeuno.BORGHERTZS_SHADOWY_HANDS,\n        xi.quest.id.jeuno.BORGHERTZS_WILD_HANDS,\n        xi.quest.id.jeuno.BORGHERTZS_HARMONIOUS_HANDS,\n        xi.quest.id.jeuno.BORGHERTZS_CHASING_HANDS,\n        xi.quest.id.jeuno.BORGHERTZS_LOYAL_HANDS,\n        xi.quest.id.jeuno.BORGHERTZS_LURKING_HANDS,\n        xi.quest.id.jeuno.BORGHERTZS_DRAGON_HANDS,\n        xi.quest.id.jeuno.BORGHERTZS_CALLING_HANDS,\n    }\n\n    local function canStartQuest(player)\n        -- Previous quest check.\n        if player:getQuestStatus(params.requiredLogId, params.requiredQuestId) == xi.questStatus.QUEST_AVAILABLE then\n            return false\n        end\n\n        -- Job check.\n        if player:getMainJob() ~= params.requiredJobId then\n            return false\n        end\n\n        -- Level check.\n        if player:getMainLvl() < 50 then\n            return false\n        end\n\n        -- Any other Borghertz quest check.\n        for i = 1, #borghertzQuests do\n            if player:getQuestStatus(xi.questLog.JEUNO, borghertzQuests[i]) == xi.questStatus.QUEST_ACCEPTED then\n                return false\n            end\n        end\n\n        return true\n    end\n\n    local function isFirstBorghertzQuest(player)\n        for i = 1, #borghertzQuests do\n            if player:getQuestStatus(xi.questLog.JEUNO, borghertzQuests[i]) == xi.questStatus.QUEST_COMPLETED then\n                return false\n            end\n        end\n\n        return true\n    end\n\n    quest.reward =\n    {\n        item = params.handAFId,\n    }\n\n    quest.sections =\n    {\n        {\n            check = function(player, status, vars)\n                return status == xi.questStatus.QUEST_AVAILABLE\n            end,\n\n            [xi.zone.UPPER_JEUNO] =\n            {\n                ['Guslam'] =\n                {\n                    onTrigger = function(player, npc)\n                        if canStartQuest(player) then\n                            quest:setVar(player, 'Option', player:getMainJob())\n                            return quest:progressEvent(155)\n                        end\n                    end,\n                },\n\n                onEventFinish =\n                {\n                    [155] = function(player, csid, option, npc)\n                        if quest:getVar(player, 'Option') == player:getMainJob() then\n                            quest:begin(player)\n                        end\n                    end,\n                },\n            },\n        },\n\n        {\n            check = function(player, status, vars)\n                return status == xi.questStatus.QUEST_ACCEPTED and\n                    not player:hasKeyItem(xi.keyItem.OLD_GAUNTLETS)\n            end,\n\n            [xi.zone.UPPER_JEUNO] =\n            {\n                ['Guslam'] = quest:event(43),\n            },\n\n            -- Old gauntlets coffer logic.\n            [params.oldGauntletZoneId] =\n            {\n                ['Treasure_Coffer'] =\n                {\n                    onTrade = function(player, npc, trade)\n                        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.OLD_GAUNTLETS)\n\n                        return quest:noAction()\n                    end,\n                },\n            },\n        },\n\n        {\n            check = function(player, status, vars)\n                return status == xi.questStatus.QUEST_ACCEPTED and\n                    player:hasKeyItem(xi.keyItem.OLD_GAUNTLETS)\n            end,\n\n            [xi.zone.CASTLE_ZVAHL_BAILEYS] =\n            {\n                ['Dark_Spark'] =\n                {\n                    onMobDeath = function(mob, player, optParams)\n                        if quest:getVar(player, 'Prog') == 4 then\n                            quest:setVar(player, 'Prog', 5)\n                        end\n                    end,\n                },\n\n                ['Torch'] =\n                {\n                    onTrigger = function(player, npc)\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if\n                            questProgress == 4 and\n                            npcUtil.popFromQM(player, npc, zones[xi.zone.CASTLE_ZVAHL_BAILEYS].mob.DARK_SPARK, { claim = true, hide = 0 })\n                        then\n                            return quest:messageSpecial(zones[xi.zone.CASTLE_ZVAHL_BAILEYS].text.SENSE_OF_FOREBODING)\n                        elseif\n                            questProgress == 5 and\n                            not player:hasKeyItem(xi.keyItem.SHADOW_FLAMES)\n                        then\n                            npcUtil.giveKeyItem(player, xi.keyItem.SHADOW_FLAMES)\n                            return quest:noAction()\n                        end\n                    end,\n                },\n            },\n\n            [xi.zone.LOWER_JEUNO] =\n            {\n                ['Yin_Pocanakhu'] =\n                {\n                    onTrigger = function(player, npc)\n                        local questProgress = quest:getVar(player, 'Prog')\n                        if questProgress == 2 then\n                            return quest:progressEvent(220)\n                        elseif questProgress == 3 or questProgress == 4 then\n                            return quest:event(221)\n                        end\n                    end,\n                },\n\n                onEventUpdate =\n                {\n                    [220] = function(player, csid, option, npc)\n                        if player:getGil() >= 1000 then\n                            player:delGil(1000)\n                            quest:setVar(player, 'Prog', 3) -- Spoken with Yin Pocanakhu.\n                            player:updateEvent(1, 1, 0, 0)\n                        else\n                            player:messageText(npc, zones[xi.zone.LOWER_JEUNO].text.YIN_POCANAKHU_GET_LOST)\n                            player:updateEvent(0, 1, 0, 0)\n                        end\n                    end,\n                },\n            },\n\n            [xi.zone.PORT_JEUNO] =\n            {\n                ['qm1'] =\n                {\n                    onTrigger = function(player, npc)\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if questProgress == 3 then\n                            return quest:progressEvent(20)\n                        elseif questProgress >= 4 and not player:hasKeyItem(xi.keyItem.SHADOW_FLAMES) then\n                            return quest:event(49)\n                        elseif questProgress == 5 and player:hasKeyItem(xi.keyItem.SHADOW_FLAMES) then\n                            return quest:progressEvent(48)\n                        end\n                    end,\n                },\n\n                onEventFinish =\n                {\n                    [20] = function(player, csid, option, npc)\n                        if option == 1 then\n                            quest:setVar(player, 'Prog', 4) -- Spoken with Borghertz. Requested \"Shadow Flames\".\n                        end\n                    end,\n\n                    [48] = function(player, csid, option, npc)\n                        if quest:complete(player) then\n                            player:addFame(xi.fameArea.SANDORIA, 7)\n                            player:addFame(xi.fameArea.BASTOK, 7)\n                            player:addFame(xi.fameArea.WINDURST, 7)\n                            player:delKeyItem(xi.keyItem.OLD_GAUNTLETS)\n                            player:delKeyItem(xi.keyItem.SHADOW_FLAMES)\n                        end\n                    end,\n                },\n            },\n\n            [xi.zone.UPPER_JEUNO] =\n            {\n                ['Deadly_Minnow'] =\n                {\n                    onTrigger = function(player, npc)\n                        if quest:getVar(player, 'Prog') == 1 then\n                            return quest:progressEvent(24)\n                        end\n                    end,\n                },\n\n                ['Guslam'] = quest:progressEvent(26),\n\n                onEventFinish =\n                {\n                    [24] = function(player, csid, option, npc)\n                        quest:setVar(player, 'Prog', 2) -- Spoken with deadly Minnow.\n                    end,\n\n                    [26] = function(player, csid, option, npc)\n                        if quest:getVar(player, 'Prog') == 0 then\n                            if isFirstBorghertzQuest(player) then\n                                quest:setVar(player, 'Prog', 1) -- Need to speak with Deadly Minnow and Yin Pocanakhu.\n                            else\n                                quest:setVar(player, 'Prog', 3) -- Skip intermediaries.\n                            end\n                        end\n                    end,\n                },\n            },\n        },\n\n        {\n            check = function(player, status, vars)\n                return status ~= xi.questStatus.QUEST_AVAILABLE and -- Quest must be already started or completed.\n                    player:getMainJob() == params.requiredJobId and -- Player must be on the appropiate job.\n                    not utils.mask.getBit(player:getCharVar('[AF]ZilartCoffer'), params.requiredJobId * 2 - 1)\n            end,\n\n            [params.optionalZoneId1] =\n            {\n                ['Treasure_Coffer'] =\n                {\n                    onTrade = function(player, npc, trade)\n                        local result = xi.treasure.onTrade(player, npc, trade, 1, params.optionalArtifact1)\n                        if result == params.optionalArtifact1 then\n                            player:incrementCharVar('[AF]ZilartCoffer', bit.lshift(1, params.requiredJobId * 2 - 1))\n                        end\n\n                        return quest:noAction()\n                    end,\n                },\n            },\n        },\n\n        {\n            check = function(player, status, vars)\n                return status ~= xi.questStatus.QUEST_AVAILABLE and\n                    player:getMainJob() == params.requiredJobId and\n                    not utils.mask.getBit(player:getCharVar('[AF]ZilartCoffer'), params.requiredJobId * 2)\n            end,\n\n            [params.optionalZoneId2] =\n            {\n                ['Treasure_Coffer'] =\n                {\n                    onTrade = function(player, npc, trade)\n                        local result = xi.treasure.onTrade(player, npc, trade, 1, params.optionalArtifact2)\n                        if result == params.optionalArtifact2 then\n                            player:incrementCharVar('[AF]ZilartCoffer', bit.lshift(1, params.requiredJobId * 2))\n                        end\n\n                        return quest:noAction()\n                    end,\n                },\n            },\n        },\n    }\n\n    self.__index = self\n    setmetatable(quest, self)\n    return quest\nend\n"},["scripts/quests/otherAreas/A_Bitter_Past.lua"]={["Path"]="scripts/quests/otherAreas/A_Bitter_Past.lua",["SHA256"]="f37809a053f41606acfad3e17e1bd011f4443bf807c0f39cdae8f74bfe12e066",["Text"]="-----------------------------------\n-- A Bitter Past\n-----------------------------------\n-- Log ID: 4, Quest ID: 66\n-- Frescheque : !pos 18 -36 12 26\n-- Raminey    : !pos 82 -35 50 26\n-- Equette    : !pos 3 -22 -17 26\n-- ???        : !pos 58 -7 27 24\n-----------------------------------\nlocal lufaiseID = zones[xi.zone.LUFAISE_MEADOWS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.A_BITTER_PAST)\nlocal orcNM = lufaiseID.mob.BLACKBONE_FRAZDIZ\n\nquest.reward =\n{\n    item = xi.item.YINYANG_LORGNETTE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Frescheque'] = quest:progressEvent(151),\n\n            onEventFinish =\n            {\n                [151] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        }\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Frescheque'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.TINY_WRISTLET) then\n                        return quest:progressEvent(154)\n                    end\n                end,\n            },\n            ['Raminey'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(152)\n                    end\n                end,\n            },\n            ['Equette'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(153)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [152] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [153] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [154] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.TINY_WRISTLET)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.LUFAISE_MEADOWS] =\n        {\n            ['qm_bitter_past'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        quest:getVar(player, 'nmKilled') ~= 1 and\n                        npcUtil.popFromQM(player, npc, { orcNM, orcNM + 1 }, { claim = true, hide = 0 })\n                    then\n                        return quest:messageText(lufaiseID.text.SENSE_OF_FOREBODING)\n                    elseif\n                        quest:getVar(player, 'nmKilled') == 1 and\n                        not player:hasKeyItem(xi.keyItem.TINY_WRISTLET)\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.TINY_WRISTLET)\n                        return quest:noAction()\n                    end\n                end,\n            },\n\n            ['Blackbone_Frazdiz'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        GetMobByID(orcNM + 1):isDead()\n                    then\n                        quest:setVar(player, 'nmKilled', 1)\n                    end\n                end,\n            },\n\n            ['Rainbringer_Yjatvot'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        GetMobByID(orcNM):isDead()\n                    then\n                        quest:setVar(player, 'nmKilled', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Equette'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(155):importantOnce()\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/A_Hard_Days_Knight.lua"]={["Path"]="scripts/quests/otherAreas/A_Hard_Days_Knight.lua",["SHA256"]="f14f055b6b5c4edb63f53180fa39296069a0b56c2e65d7b4e020abc125d77308",["Text"]="-----------------------------------\n-- A Hard Day's Knight\n-----------------------------------\n-- Log ID: 4, Quest ID: 64\n-- Quelveuiat          : !pos -3.177 -22.750 -25.970 26\n-- qm_hard_days_knight : !pos -38.605 -9.022 -290.700 24\n-----------------------------------\nlocal lufaiseID = zones[xi.zone.LUFAISE_MEADOWS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.A_HARD_DAYS_KNIGHT)\n\nquest.reward =\n{\n    gil = 2100,\n    title = xi.title.TAVNAZIAN_SQUIRE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Quelveuiat'] = quest:progressEvent(119),\n\n            onEventFinish =\n            {\n                [119] = function(player, csid, option, npc)\n                    if option == 3 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Quelveuiat'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:event(120)\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(121)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [121] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.LUFAISE_MEADOWS] =\n        {\n            ['qm_hard_days_knight'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not GetMobByID(lufaiseID.mob.SPLINTERSPINE_GRUKJUK):isSpawned() and\n                        quest:getVar(player, 'Prog') < 1\n                    then\n                        player:messageSpecial(lufaiseID.text.SURVEY_THE_SURROUNDINGS)\n                        SpawnMob(lufaiseID.mob.SPLINTERSPINE_GRUKJUK):updateClaim(player)\n                        return quest:messageSpecial(lufaiseID.text.MURDEROUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Splinterspine_Grukjuk'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Quelveuiat'] =\n            {\n                onTrade = function(player, npc, trade)\n                    -- TODO: Needs verification for single-trade events\n                    if not player:hasKeyItem(xi.keyItem.TEMPLE_KNIGHT_KEY) then\n                        if\n                            npcUtil.tradeHasExactly(trade, xi.item.SEALION_CREST_KEY) or\n                            npcUtil.tradeHasExactly(trade, xi.item.CORAL_CREST_KEY)\n                        then\n                            return quest:progressEvent(631, trade:getItemId())\n                        elseif npcUtil.tradeHasExactly(trade, { xi.item.SEALION_CREST_KEY, xi.item.CORAL_CREST_KEY }) then\n                            quest:setVar(player, 'Prog', 2)\n                            return quest:progressEvent(631, xi.item.SEALION_CREST_KEY, xi.item.CORAL_CREST_KEY)\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local itemCount = 0\n                    local itemTable = { 0, 0 }\n\n                    for itemId = xi.item.SEALION_CREST_KEY, xi.item.CORAL_CREST_KEY do\n                        if player:findItem(itemId) then\n                            itemCount = itemCount + 1\n                            itemTable[itemCount] = itemId\n                        end\n                    end\n\n                    return quest:progressEvent(631, itemTable[1], itemTable[2])\n                end,\n            },\n\n            onEventFinish =\n            {\n                [631] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        -- TODO: This is most likely not retail accurate, and need to check captures\n                        -- for forced zoning events.\n                        player:startEvent(632)\n                    end\n                end,\n\n                [632] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 0)\n                    npcUtil.giveKeyItem(player, xi.keyItem.TEMPLE_KNIGHT_KEY)\n                end\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/An_Explorers_Footsteps.lua"]={["Path"]="scripts/quests/otherAreas/An_Explorers_Footsteps.lua",["SHA256"]="3ba3d57b9e5db0f2c457e8018fa7a339bdf16be3d7eda2e6409852f21773c62c",["Text"]="-----------------------------------\n-- An Explorer's Footsteps\n-----------------------------------\n-- Log ID: 4, Quest ID: 19\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.AN_EXPLORERS_FOOTSTEPS)\n\nlocal monumentTable =\n{\n    [xi.zone.WEST_RONFAURE          ] = {  0,   800 }, -- !pos -183.734 -12.6798 -395.7220 100\n    [xi.zone.EAST_RONFAURE          ] = {  1,   800 }, -- !pos   77.277  -2.894  -517.3760 101\n    [xi.zone.EAST_RONFAURE_S        ] = {  1,   800 }, -- !pos   77.277  -2.894  -517.3760  81\n    [xi.zone.LA_THEINE_PLATEAU      ] = {  2,  1000 }, -- !pos  334.133  50.6223  141.1630 102\n    [xi.zone.VALKURM_DUNES          ] = {  3,  1000 }, -- !pos -311.299  -4.4211 -138.8780 103\n    [xi.zone.JUGNER_FOREST          ] = {  4,  1000 }, -- !pos  -65.976 -23.8312 -661.3620 104\n    [xi.zone.JUGNER_FOREST_S        ] = {  4,  1000 }, -- !pos  -65.976 -23.8312 -661.3620  82\n    [xi.zone.BATALLIA_DOWNS         ] = {  5, 10000 }, -- !pos  185.669   9.0476 -614.0250 105\n    [xi.zone.BATALLIA_DOWNS_S       ] = {  5, 10000 }, -- !pos  185.669   9.0476 -614.0250  84\n    [xi.zone.NORTH_GUSTABERG        ] = {  6,  3000 }, -- !pos -199.635  96.0547  505.6240 106\n    [xi.zone.SOUTH_GUSTABERG        ] = {  7,   800 }, -- !pos  520.064  -5.8831 -738.3560 107\n    [xi.zone.KONSCHTAT_HIGHLANDS    ] = {  8,  1000 }, -- !pos -102.355   7.9796  253.7059 108\n    [xi.zone.PASHHOW_MARSHLANDS     ] = {  9,  1000 }, -- !pos -300.672  21.6038  304.1790 109\n    [xi.zone.PASHHOW_MARSHLANDS_S   ] = {  9,  1000 }, -- !pos -300.672  21.6038  304.1790  90\n    [xi.zone.ROLANBERRY_FIELDS      ] = { 10,  3000 }, -- !pos  362.479 -34.8962 -398.9940 110\n    [xi.zone.ROLANBERRY_FIELDS_S    ] = { 10,  3000 }, -- !pos  362.479 -34.8962 -398.9940  91\n    [xi.zone.WEST_SARUTABARUTA      ] = { 11,   800 }, -- !pos -205.593 -23.2401 -119.6700 115\n    [xi.zone.WEST_SARUTABARUTA_S    ] = { 11,   800 }, -- !pos -205.593 -23.2401 -119.6700  95\n    [xi.zone.EAST_SARUTABARUTA      ] = { 12,   800 }, -- !pos  448.045  -7.8100  319.9799 116\n    [xi.zone.TAHRONGI_CANYON        ] = { 13,  1000 }, -- !pos -499.189  12.6524  373.5920 117\n    [xi.zone.BUBURIMU_PENINSULA     ] = { 14,  1000 }, -- !pos  320.755  -4.0779  368.7219 118\n    [xi.zone.MERIPHATAUD_MOUNTAINS  ] = { 15,  1000 }, -- !pos  450.741   2.1088 -290.7359 119\n    [xi.zone.MERIPHATAUD_MOUNTAINS_S] = { 15,  1000 }, -- !pos  450.741   2.1088 -290.7359  97\n    [xi.zone.SAUROMUGUE_CHAMPAIGN   ] = { 16, 10000 }, -- !pos   77.544  -2.7476 -184.8030 120\n    [xi.zone.SAUROMUGUE_CHAMPAIGN_S ] = { 16, 10000 }, -- !pos   77.544  -2.7476 -184.8030  98\n}\n\nlocal function abelardAccept(player, option)\n    if option == 100 then\n        if npcUtil.giveItem(player, xi.item.LUMP_OF_SELBINA_CLAY) then\n            player:setLocalVar('[EF]ClayRecieved', 1)\n\n            -- Decide monument to request.\n            local monumentBitmask = player:getCharVar('[EF]MonumentBitmask')\n\n            for i = 0, 16 do\n                if not utils.mask.getBit(monumentBitmask, i) then\n                    quest:setVar(player, '[EF]TargetMonument', i)\n\n                    break\n                end\n            end\n\n            -- Start quest.\n            quest:begin(player)\n        end\n    end\nend\n\nlocal function abelardCorrectTrade(player, csid, option)\n    -- Handle gil reward.\n    player:confirmTrade()\n    npcUtil.giveCurrency(player, 'gil', monumentTable[quest:getVar(player, '[EF]TabletZoneId')][2])\n\n    -- Complete quest.\n    if csid == 47 then\n        player:setCharVar('[EF]MonumentBitmask', 0)\n        player:setCharVar('[EF]MonumentCount', 0)\n        npcUtil.giveKeyItem(player, xi.keyItem.MAP_OF_THE_CRAWLERS_NEST)\n        quest:complete(player)\n\n    -- Continue quest.\n    elseif option == 100 then\n        abelardAccept(player, option)\n\n    -- Abort quest. Delete from log BUT remember tablets already given.\n    elseif option == 110 then\n        player:delQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.AN_EXPLORERS_FOOTSTEPS)\n    end\nend\n\nlocal handleStoneMonument =\n{\n    ['Stone_Monument'] =\n    {\n        onTrade = function(player, npc, trade)\n            if npcUtil.tradeHasExactly(trade, xi.item.LUMP_OF_SELBINA_CLAY) then\n                player:confirmTrade()\n                npcUtil.giveItem(player, xi.item.CLAY_TABLET)\n                quest:setVar(player, '[EF]TabletZoneId', player:getZoneID())\n            end\n        end,\n    },\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= 10 -- Level requirement added in the March 8, 2007 update: https://www.playonline.com/pcd/update/ff11us/20070308c2bbd1/detail.html\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Abelard'] =\n            {\n                onTrigger = function(player, npc)\n                    local monumentBitmask = player:getCharVar('[EF]MonumentBitmask')\n\n                    if monumentBitmask == 0 then\n                        return quest:progressEvent(40) -- First time.\n                    else\n                        return quest:progressEvent(42) -- Declined further interaction after previously accepting and trading tablet.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [40] = function(player, csid, option, npc)\n                    abelardAccept(player, option)\n                end,\n\n                [42] = function(player, csid, option, npc)\n                    abelardAccept(player, option)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        -- Monuments\n        [xi.zone.WEST_RONFAURE          ] = handleStoneMonument,\n        [xi.zone.EAST_RONFAURE          ] = handleStoneMonument,\n        [xi.zone.EAST_RONFAURE_S        ] = handleStoneMonument,\n        [xi.zone.LA_THEINE_PLATEAU      ] = handleStoneMonument,\n        [xi.zone.VALKURM_DUNES          ] = handleStoneMonument,\n        [xi.zone.JUGNER_FOREST          ] = handleStoneMonument,\n        [xi.zone.JUGNER_FOREST_S        ] = handleStoneMonument,\n        [xi.zone.BATALLIA_DOWNS         ] = handleStoneMonument,\n        [xi.zone.BATALLIA_DOWNS_S       ] = handleStoneMonument,\n        [xi.zone.NORTH_GUSTABERG        ] = handleStoneMonument,\n        [xi.zone.SOUTH_GUSTABERG        ] = handleStoneMonument,\n        [xi.zone.KONSCHTAT_HIGHLANDS    ] = handleStoneMonument,\n        [xi.zone.PASHHOW_MARSHLANDS     ] = handleStoneMonument,\n        [xi.zone.PASHHOW_MARSHLANDS_S   ] = handleStoneMonument,\n        [xi.zone.ROLANBERRY_FIELDS      ] = handleStoneMonument,\n        [xi.zone.ROLANBERRY_FIELDS_S    ] = handleStoneMonument,\n        [xi.zone.WEST_SARUTABARUTA      ] = handleStoneMonument,\n        [xi.zone.WEST_SARUTABARUTA_S    ] = handleStoneMonument,\n        [xi.zone.EAST_SARUTABARUTA      ] = handleStoneMonument,\n        [xi.zone.TAHRONGI_CANYON        ] = handleStoneMonument,\n        [xi.zone.BUBURIMU_PENINSULA     ] = handleStoneMonument,\n        [xi.zone.MERIPHATAUD_MOUNTAINS  ] = handleStoneMonument,\n        [xi.zone.MERIPHATAUD_MOUNTAINS_S] = handleStoneMonument,\n        [xi.zone.SAUROMUGUE_CHAMPAIGN   ] = handleStoneMonument,\n        [xi.zone.SAUROMUGUE_CHAMPAIGN_S ] = handleStoneMonument,\n\n        -- Quest giver\n        [xi.zone.SELBINA] =\n        {\n            ['Abelard'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.CLAY_TABLET) then\n                        local currentMonument   = monumentTable[quest:getVar(player, '[EF]TabletZoneId')][1]\n                        local requestedMonument = quest:getVar(player, '[EF]TargetMonument')\n\n                        -- We already traded that monument tablet.\n                        if utils.mask.getBit(player:getCharVar('[EF]MonumentBitmask'), currentMonument) then\n                            return quest:event(45)\n\n                        -- We never traded that monument tablet.\n                        else\n                            player:incrementCharVar('[EF]MonumentBitmask', bit.lshift(1, currentMonument))\n                            player:incrementCharVar('[EF]MonumentCount', 1)\n\n                            if player:getCharVar('[EF]MonumentCount') == 17 then\n                                return quest:progressEvent(47) -- Traded them all.\n                            elseif currentMonument == requestedMonument then\n                                return quest:progressEvent(41) -- Traded suggested one.\n                            else\n                                return quest:progressEvent(46) -- Traded different one.\n                            end\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    -- You are supposed to have one of them. If not, you must have zoned before getting a new Clay.\n                    if\n                        not player:hasItem(xi.item.CLAY_TABLET) and\n                        not player:hasItem(xi.item.LUMP_OF_SELBINA_CLAY) and\n                        player:getLocalVar('[EF]ClayRecieved') ~= 1\n                    then\n                        return quest:event(44)\n\n                    -- Monument clue (Events 43 and 49)\n                    else\n                        local eventParam = quest:getVar(player, '[EF]TargetMonument')\n                        if eventParam >= 9 then\n                            return quest:event(49, eventParam - 9)\n                        else\n                            return quest:event(43, eventParam)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                -- Requested monument.\n                [41] = function(player, csid, option, npc)\n                    abelardCorrectTrade(player, csid, option)\n                end,\n\n                -- Lost Clay and don't have tablet either.\n                [44] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.LUMP_OF_SELBINA_CLAY) then\n                        player:setLocalVar('[EF]ClayRecieved', 1)\n                    end\n                end,\n\n                -- Had already traded this monument tablet.\n                [45] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.LUMP_OF_SELBINA_CLAY) then\n                        player:confirmTrade()\n                        player:setLocalVar('[EF]ClayRecieved', 1)\n                    end\n                end,\n\n                -- Different than requested monument tablet.\n                [46] = function(player, csid, option, npc)\n                    abelardCorrectTrade(player, csid, option)\n                end,\n\n                -- Complete quest.\n                [47] = function(player, csid, option, npc)\n                    abelardCorrectTrade(player, csid, option)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Abelard'] = quest:event(48):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Behind_the_Smile.lua"]={["Path"]="scripts/quests/otherAreas/Behind_the_Smile.lua",["SHA256"]="368f7bccda4e73e03f35b9f9bb76fd08537490110f68966cbef9504dc7427f6a",["Text"]="-----------------------------------\n-- Behind the Smile\n-----------------------------------\n-- Log ID: 4, Quest ID: 77\n-- Enaremand : !pos 96.514 -41 51.613\n-----------------------------------\nlocal carpentersLandingID  = zones[xi.zone.CARPENTERS_LANDING]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.BEHIND_THE_SMILE)\n\nquest.reward =\n{\n    item  = xi.item.MANNEQUIN_PUMPS,\n}\n\nquest.sections =\n{\n    -- START: Talk to Enaremand (J-7) on the upper level in Tavnazian Safehold\n    -- QUEST AVAILABLE\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ITS_RAINING_MANNEQUINS)\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Enaremand'] = quest:progressEvent(533),\n\n            onEventFinish =\n            {\n                [533] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- QUEST ACCEPTED\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Enaremand'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.RED_OIL) then\n                        return quest:progressEvent(534)\n                    else\n                        return quest:event(541)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [534] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.RED_OIL)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.MHAURA] =\n        {\n            ['Fyi_Chalmwoh'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(320)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [320] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.CARPENTERS_LANDING] =\n        {\n            ['qm_behind_the_smile'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    if\n                        questProgress == 1 and\n                        not GetMobByID(carpentersLandingID.mob.BULLHEADED_GROSVEZ):isSpawned()\n                    then\n                        SpawnMob(carpentersLandingID.mob.BULLHEADED_GROSVEZ):updateClaim(player)\n                        return quest:messageSpecial(carpentersLandingID.text.STENCH_OF_DECAY)\n                    elseif questProgress == 2 then\n                        quest:setVar(player, 'Prog', 3)\n                        npcUtil.giveKeyItem(player, xi.keyItem.RED_OIL)\n                        return quest:noAction()\n                    end\n                end,\n            },\n\n            ['Bullheaded_Grosvez'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n        }\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Better_The_Demon_You_Know.lua"]={["Path"]="scripts/quests/otherAreas/Better_The_Demon_You_Know.lua",["SHA256"]="d9d3ee007fbfdc0ecaea813e172a993c8899cfd679ef5035d3fa8056cc1baae9",["Text"]="-----------------------------------\n-- Better The Demon You Know\n-----------------------------------\n-- Log ID: 4, Quest ID: 105\n-- Koblakiq !pos -64.851 21.834 -117.521\n-- qm2      !pos 19.4 -24.141 19.185\n-----------------------------------\nlocal zvahlID = zones[xi.zone.CASTLE_ZVAHL_BAILEYS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.BETTER_THE_DEMON_YOU_KNOW)\n\nquest.reward =\n{\n    item  = xi.item.GOBLIN_GRENADE,\n    title = xi.title.APOSTATE_FOR_HIRE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.FOR_THE_BIRDS) and\n                not xi.quest.getMustZone(player, xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.FOR_THE_BIRDS)\n        end,\n\n        [xi.zone.OLDTON_MOVALPOLOS] =\n        {\n            ['Koblakiq'] = quest:progressCutscene(20, 0, xi.item.DEMON_PEN),\n\n            onEventFinish =\n            {\n                [20] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.OLDTON_MOVALPOLOS] =\n        {\n            ['Koblakiq'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n                    local waitTime = quest:getVar(player, 'Wait')\n\n                    if progress == 0 then\n                        return quest:event(21, 0, xi.item.DEMON_PEN):setPriority(101) -- Reminder to get Demon Pen\n                    elseif progress == 1 then\n                        if GetSystemTime() >= waitTime then\n                            return quest:progressCutscene(24) -- Go to Castle Zvahl Baileys\n                        else\n                            return quest:event(23):setPriority(101) -- Wait Longer\n                        end\n                    elseif progress == 2 then\n                        return quest:event(25):setPriority(101) -- Reminder to go to castle Zvahl Baileys\n                    elseif progress == 3 then\n                        return quest:progressCutscene(26)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.DEMON_PEN) then\n                        return quest:progressCutscene(22)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [22] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 1)\n                    -- TODO: Check when the wait starts and how it is rounded. Retail can advance less than a minute after this cutscene.\n                    quest:setVar(player, 'Wait', GetSystemTime() + 60) -- 1 Minute wait time\n                end,\n\n                [24] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [26] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.ZEELOZOKS_EARPLUG)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.CASTLE_ZVAHL_BAILEYS] =\n        {\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if\n                        player:getLocalVar('NMKilled') == 1 and\n                        progress == 2\n                    then\n                        player:addKeyItem(xi.keyItem.ZEELOZOKS_EARPLUG)\n                        quest:setVar(player, 'Prog', 3)\n                        return quest:messageSpecial(zvahlID.text.KEYITEM_OBTAINED, xi.keyItem.ZEELOZOKS_EARPLUG)\n                    elseif\n                        progress == 2 and\n                        not GetMobByID(zvahlID.mob.MARQUIS_ANDREALPUS):isSpawned() and\n                        not GetMobByID(zvahlID.mob.MARQUIS_ANDREALPUS + 1):isSpawned() and\n                        not GetMobByID(zvahlID.mob.MARQUIS_ANDREALPUS + 2):isSpawned() and\n                        not GetMobByID(zvahlID.mob.MARQUIS_ANDREALPUS + 3):isSpawned() and\n                        not GetMobByID(zvahlID.mob.MARQUIS_ANDREALPUS + 4):isSpawned()\n                    then\n                        for i = 0, 4 do\n                            SpawnMob(zvahlID.mob.MARQUIS_ANDREALPUS + i):updateClaim(player)\n                        end\n\n                        player:messageSpecial(zvahlID.text.MOBLIN_EARPLUG_ON_THE_GROUND)\n                        return quest:messageSpecial(zvahlID.text.MARQUIS_ATTACKS)\n                    end\n                end,\n            },\n\n            ['Marquis_Andrealphus'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        player:setLocalVar('NMKilled', 1) -- If the player zones before getting the KI they need to refight the NM.\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.OLDTON_MOVALPOLOS] =\n        {\n            ['Koblakiq'] = quest:event(27):replaceDefault()\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Bombs_Away.lua"]={["Path"]="scripts/quests/otherAreas/Bombs_Away.lua",["SHA256"]="4f0b57e6ea6650c2b4f3a2cf3a865f8511cf3a0dc0b84a4063f2078dfdccbe36",["Text"]="-----------------------------------\n-- Bombs Away!\n-----------------------------------\n-- Log ID: 4, Quest ID: 96\n-- Buffalostalker_Dodzbraz : !pos -380.171 -24.89 -180.797 5\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.BOMBS_AWAY)\n\nquest.reward =\n{\n    item  = xi.item.CHUNK_OF_SHUMEYO_SALT,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.ULEGUERAND_RANGE] =\n        {\n            ['Buffalostalker_Dodzbraz'] = quest:progressEvent(6),\n\n            onEventFinish =\n            {\n                [6] = function(player, csid, option, npc)\n                    if option == 1 then -- You climb mountain.\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.ULEGUERAND_RANGE] =\n        {\n            ['Buffalostalker_Dodzbraz'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(7)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.CLUSTER_CORE, 2 } }) then\n                        return quest:progressEvent(8) -- Quest completed dialog.\n                    end\n                end,\n\n            },\n\n            onEventFinish =\n            {\n                [8] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Confessions_of_a_Bellmaker.lua"]={["Path"]="scripts/quests/otherAreas/Confessions_of_a_Bellmaker.lua",["SHA256"]="12cef1567d8519ff3451dd2a66db358bf1e7290022b08ce65c8c23ff731de4db",["Text"]="-----------------------------------\n-- Confessions of a Bellmaker\n-- Stone Monument !pos -733 -46 -300 30\n-- Reinberta !pos -190 -7 -59 235\n-- Mevreauche !pos -193 11 148 231\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.CONFESSIONS_OF_A_BELLMAKER)\n\nquest.reward =\n{\n    item = xi.item.MINSTRELS_DAGGER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.RIVERNE_SITE_A01] =\n        {\n            ['Stone_Monument'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressCutscene(101)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [101] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.ORNAMENTED_SCROLL)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RIVERNE_SITE_A01] =\n        {\n            ['Stone_Monument'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressCutscene(102)\n                    elseif quest:getVar(player, 'Prog') == 3 then\n                        local monumentObj = GetNPCByID(zones[xi.zone.RIVERNE_SITE_A01].npc.STONE_MONUMENT)\n\n                        if monumentObj then\n                            -- TODO: Determine if message is displayed on NM pop, return message if this is successful, else\n                            -- noAction()\n                            npcUtil.popFromQM(player, monumentObj, zones[xi.zone.RIVERNE_SITE_A01].mob.ARCANE_PHANTASM, { hide = 0 })\n                        end\n\n                        return quest:noAction()\n                    elseif quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressCutscene(103)\n                    end\n                end,\n            },\n\n            ['Arcane_Phantasm'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [102] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [103] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.ORNAMENTED_SCROLL)\n                    end\n                end,\n            },\n        },\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Reinberta'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(402)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [402] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Mevreauche'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(74)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [74] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Elder_Memories.lua"]={["Path"]="scripts/quests/otherAreas/Elder_Memories.lua",["SHA256"]="4362d2ae18183dd78b3c0f6130711ad405cd7aa302920fdc7b40eac34b22d82a",["Text"]="-----------------------------------\n-- Elder Memories\n-----------------------------------\n-- Log ID: 4, Quest ID: 24\n-- !addquest 4 24\n-- Isacio : !pos -54 -1 -44 248\n-----------------------------------\n-- Mutually exclusive with The Old Lady. Cannot be started if The Old Lady has been started or completed.\n-----------------------------------\nlocal selbinaID = zones[xi.zone.SELBINA]\n-----------------------------------\n\nlocal subJobItems =\n{\n    [0] = { item = xi.item.MAGICKED_SKULL, tradeEvent = 115 },\n    [1] = { item = xi.item.DAMSELFLY_WORM, tradeEvent = 116 },\n    [2] = { item = xi.item.CRAB_APRON,     tradeEvent = 117 },\n}\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ELDER_MEMORIES)\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_OLD_LADY) == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Isacio'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getMainLvl() >= xi.settings.main.SUBJOB_QUEST_LEVEL then\n                        return quest:progressEvent(111, xi.item.MAGICKED_SKULL) -- Player is eligible for the quest.\n                    else\n                        return quest:event(119) -- Player level is too low to be offered the quest.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [111] = function(player, csid, option, npc)\n                    if option == 40 then -- Accepted quest.\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Vera'] = quest:event(130):replaceDefault(),\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Isacio'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    local step          = subJobItems[questProgress]\n\n                    if step and npcUtil.tradeMatches(trade, { { step.item, 1 } }) then\n                        local nextStep = subJobItems[questProgress + 1]\n\n                        if nextStep then\n                            return quest:progressEvent(step.tradeEvent, nextStep.item)\n                        else\n                            return quest:progressEvent(step.tradeEvent)\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    -- Obtained from Rhapsodies of Vanadiel 1-4, allows player to skip the item collection.\n                    if player:hasKeyItem(xi.keyItem.GILGAMESHS_INTRODUCTORY_LETTER) then\n                        return quest:progressEvent(117)\n                    end\n\n                    local step = subJobItems[quest:getVar(player, 'Prog')]\n                    if step then\n                        return quest:event(114, step.item)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [115] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [116] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [117] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:unlockJob(0)\n                        player:messageSpecial(selbinaID.text.SUBJOB_UNLOCKED)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Vera'] = quest:event(130):replaceDefault(),\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Isacio'] = quest:event(118):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Elderly_Pursuits.lua"]={["Path"]="scripts/quests/otherAreas/Elderly_Pursuits.lua",["SHA256"]="743c75a363eb683a69f5c31ad856b2339b86eaa6eef43eb3fa7252a4accad313",["Text"]="-----------------------------------\n-- Elderly Pursuits\n-----------------------------------\n-- Log ID: 4, Quest ID: 75\n-----------------------------------\n-- Pre-requisite Completed Secrets of Oven Lost Log ID: 4, Quest ID: 73\n-----------------------------------\n-- Despachiaire     !pos 111.2090 -40.0148 -85.4810\n-- Rouva            !pos -16.3326 2.1 10.3829\n-- Para NM ???      !pos -414.915 0 -362.9870\n-----------------------------------\nlocal ID = zones[xi.zone.CARPENTERS_LANDING]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ELDERLY_PURSUITS)\n\nquest.reward =\n{\n    item = xi.item.ELEGANT_RIBBON,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:hasCompletedQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.SECRETS_OF_OVENS_LOST)\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Despachiaire'] = quest:progressEvent(517),\n\n            onEventFinish =\n            {\n                [517] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.ANTIQUE_AMULET)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog <= 2\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Rouva'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANTIQUE_AMULET) then\n                        return quest:progressEvent(747)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [747] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.CARPENTERS_LANDING] =\n        {\n            ['qm_para'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.popFromQM(player, npc, ID.mob.PARA, { claim = true, hide = 0 })\n                    then\n                        return quest:messageSpecial(ID.text.STENCH_OF_DECAY)\n                    elseif\n                        quest:getVar(player, 'Prog') == 2 and\n                        player:hasKeyItem(xi.keyItem.ANTIQUE_AMULET)\n                    then\n                        quest:setVar(player, 'Prog', 3)\n                        player:delKeyItem(xi.keyItem.ANTIQUE_AMULET)\n                        player:addKeyItem(xi.keyItem.CATHEDRAL_MEDALLION)\n                        player:messageSpecial(ID.text.POLISH_MUSHROOM_SPORE, xi.keyItem.ANTIQUE_AMULET)\n                        return quest:messageSpecial(ID.text.KEYITEM_OBTAINED, xi.keyItem.CATHEDRAL_MEDALLION)\n                    end\n                end,\n            },\n\n            --The player only needs to kill the original Para. There are player reports of them killing the original getting the KI and chaining the clones to zone.\n            ['Para'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if\n                        mob:getID() == ID.mob.PARA and\n                        quest:getVar(player, 'Prog') == 1\n                    then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n\n            -- Resets the progress if the player killed Para but didn't check the ??? before zoning. Will result in the player needing to refight.\n            onZoneOut = function(player)\n                if quest:getVar(player, 'Prog') == 2 then\n                    quest:setVar(player, 'Prog', 1)\n                end\n            end,\n        },\n    },\n\n    {\n\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog >= 3\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Rouva'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.CATHEDRAL_MEDALLION) then\n                        return quest:progressEvent(748)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [748] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Despachiaire'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(518)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [518] = function(player, csid, option, npc)\n                    quest:complete(player)\n                    player:delKeyItem(xi.keyItem.CATHEDRAL_MEDALLION)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/For_The_Birds.lua"]={["Path"]="scripts/quests/otherAreas/For_The_Birds.lua",["SHA256"]="ebb819bfa32de917564046e5d49506a561ab8084c4baf4111aaa9c125680305c",["Text"]="-----------------------------------\n-- For the Birds\n-----------------------------------\n-- Log ID: 4, Quest ID: 104\n-- Koblakiq          !pos -64.851 21.834 -117.521\n-- Daa Bola the Seer !pos -159.69 -16.26 191.923\n-- GeFhu Yagudoeye   !pos -91.354 -3.251 -127.831\n-----------------------------------\nlocal castleID   = zones[xi.zone.CASTLE_OZTROJA]\nlocal beadeauxID = zones[xi.zone.BEADEAUX]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.FOR_THE_BIRDS)\n\nquest.reward =\n{\n    item = xi.item.JAGUAR_MANTLE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.MISSIONARY_MOBLIN) and\n                not xi.quest.getMustZone(player, xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.MISSIONARY_MOBLIN)\n        end,\n\n        [xi.zone.OLDTON_MOVALPOLOS] =\n        {\n            ['Koblakiq'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressCutscene(14, 0, xi.item.ARNICA_ROOT)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [14] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.OLDTON_MOVALPOLOS] =\n        {\n            ['Koblakiq'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:event(15) -- Reminder\n                    elseif progress == 1 then\n                        return quest:progressEvent(16, 0, xi.keyItem.GLITTERING_FRAGMENT)\n                    elseif progress == 2 then\n                        return quest:event(17) -- Reminder\n                    elseif progress == 4 then\n                        return quest:progressCutscene(18)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [16] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    npcUtil.giveKeyItem(player, xi.keyItem.GLITTERING_FRAGMENT)\n                end,\n\n                [18] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.CASTLE_OZTROJA] =\n        {\n            ['Daa_Bola_the_Seer'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.ARNICA_ROOT) then\n                        return quest:progressCutscene(87)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:event(86)\n                    elseif quest:getMustZone(player) then\n                        return quest:messageSpecial(castleID.text.LETTING_YOU_GO)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [87] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 1)\n                    quest:setMustZone(player)\n                end,\n            },\n        },\n\n        [xi.zone.BEADEAUX] =\n        {\n            ['GeFhu_Yagudoeye'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if\n                        progress == 3 and\n                        quest:getVar(player, 'Option') == 4\n                    then\n                        return quest:progressCutscene(124)\n                    elseif\n                        progress == 2 and\n                        not GetMobByID(beadeauxID.mob.MAGNES_QUADAV_NM):isSpawned() and\n                        not GetMobByID(beadeauxID.mob.MAGNES_QUADAV_NM + 1):isSpawned() and\n                        not GetMobByID(beadeauxID.mob.NICKEL_QUADAV_NM):isSpawned() and\n                        not GetMobByID(beadeauxID.mob.NICKEL_QUADAV_NM + 1):isSpawned()\n                    then\n                        quest:setVar(player, 'Prog', 3)\n                        for\n                            i = 0, 3 do SpawnMob(beadeauxID.mob.MAGNES_QUADAV_NM + i):updateClaim(player)\n                        end\n\n                        player:delKeyItem(xi.keyItem.GLITTERING_FRAGMENT)\n                        player:messageSpecial(beadeauxID.text.TAKEN_FROM_YOU, 0, xi.keyItem.GLITTERING_FRAGMENT)\n                        return quest:messageSpecial(beadeauxID.text.QUADAV_ARE_ATTACKING)\n                    elseif\n                        progress == 3 and\n                        not GetMobByID(beadeauxID.mob.MAGNES_QUADAV_NM):isSpawned() and\n                        not GetMobByID(beadeauxID.mob.MAGNES_QUADAV_NM + 1):isSpawned() and\n                        not GetMobByID(beadeauxID.mob.NICKEL_QUADAV_NM):isSpawned() and\n                        not GetMobByID(beadeauxID.mob.NICKEL_QUADAV_NM + 1):isSpawned()\n                    then\n                        for\n                            i = 0, 3 do SpawnMob(beadeauxID.mob.MAGNES_QUADAV_NM + i):updateClaim(player)\n                        end\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n\n            ['Magnes_Quadav_NM'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    local questOption = quest:getVar(player, 'Option')\n\n                    if quest:getVar(player, 'Prog') == 3 then\n                        quest:setVar(player, 'Option', questOption + 1)\n                    end\n                end,\n            },\n\n            ['Nickel_Quadav_NM'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    local questOption = quest:getVar(player, 'Option')\n\n                    if quest:getVar(player, 'Prog') == 3 then\n                        quest:setVar(player, 'Option', questOption + 1)\n                    end\n                end,\n            },\n\n            onZoneOut = function(player)\n                if quest:getVar(player, 'Prog') >= 2 then\n                    quest:setVar(player, 'Option', 0)\n                end\n            end,\n\n            onEventFinish =\n            {\n                [124] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                quest:getMustZone(player)\n        end,\n\n        [xi.zone.OLDTON_MOVALPOLOS] =\n        {\n            ['Koblakiq'] = quest:event(19),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Give_a_Moogle_a_Break.lua"]={["Path"]="scripts/quests/otherAreas/Give_a_Moogle_a_Break.lua",["SHA256"]="be73e4e988050891f8fddd8d6fc95d4453f759cb7af894e3816bcc997d202d59",["Text"]="-----------------------------------\n-- Give a Moogle a Break\n-----------------------------------\n-- Log ID: 4, Quest ID: 100\n-- Moogle : (Mog House, Home Nation)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.GIVE_A_MOOGLE_A_BREAK)\n\nquest.reward =\n{\n    title = xi.title.MOGS_KIND_MASTER,\n}\n\n-- Every Mog House zone shares one section table.\nquest.sections = {}\n\nquest.sections[1] =\n{\n    check = function(player, status, vars)\n        local bedPlacedTime = quest:getVar(player, 'bedPlacedTime')\n\n        return status == xi.questStatus.QUEST_AVAILABLE and\n            xi.moghouse.inMogHouseInHomeNation(player) and\n            player:getFameLevel(player:getNation()) >= 3 and\n            quest:getLocalVar(player, 'mustZone') == 0 and\n            quest:getLocalVar(player, 'questSeen') == 0 and\n            bedPlacedTime ~= 0 and\n            GetSystemTime() > bedPlacedTime + 60\n    end\n}\n\n---@type ZoneSection\nlocal questAvailable =\n{\n    ['Moogle'] =\n    {\n        onTrigger = function(player, npc)\n            return quest:progressEvent(30005, 0, 0, 0, 5, 0, xi.item.POWER_BOW, xi.item.BEETLE_RING)\n        end,\n    },\n\n    onEventFinish =\n    {\n        [30005] = function(player, csid, option, npc)\n            quest:setLocalVar(player, 'questSeen', 1)\n\n            if option == 1 then\n                quest:begin(player)\n            end\n        end,\n    },\n}\n\nquest.sections[2] =\n{\n    check = function(player, status, vars)\n        return status == xi.questStatus.QUEST_ACCEPTED\n    end\n}\n\n---@type ZoneSection\nlocal questAccepted =\n{\n    ['Moogle'] =\n    {\n        onTrade = function(player, npc, trade)\n            if npcUtil.tradeMatches(trade, { { xi.item.POWER_BOW, 1 }, { xi.item.BEETLE_RING, 1 } }) then\n                return quest:progressEvent(30007)\n            end\n        end,\n\n        onTrigger = function(player, npc)\n            local questProgress = quest:getVar(player, 'Prog')\n            local questSeen = quest:getLocalVar(player, 'questSeen')\n\n            if questSeen ~= 0 then\n                return nil\n            end\n\n            if questProgress == 0 then\n                return quest:progressEvent(30006, 0, 0, 0, 0, 0, xi.item.POWER_BOW, xi.item.BEETLE_RING)\n            elseif\n                questProgress == 1 and\n                quest:getVar(player, 'Timer') < GetSystemTime()\n            then\n                return quest:progressEvent(30008)\n            end\n        end,\n    },\n\n    onEventFinish =\n    {\n        [30006] = function(player, csid, option, npc)\n            quest:setLocalVar(player, 'questSeen', 1)\n        end,\n\n        [30007] = function(player, csid, option, npc)\n            player:tradeComplete()\n            quest:setVar(player, 'Prog', 1)\n            quest:setVar(player, 'Timer', GetSystemTime() + 60)\n        end,\n\n        [30008] = function(player, csid, option, npc)\n            if quest:complete(player) then\n                player:changeContainerSize(xi.inv.MOGSAFE, 10)\n                player:changeContainerSize(xi.inv.MOGSAFE2, 10)\n            end\n        end,\n    },\n}\n\nfor _, zoneId in ipairs(xi.moghouse.moghouseZones) do\n    quest.sections[1][zoneId] = questAvailable\n    quest.sections[2][zoneId] = questAccepted\nend\n\nreturn quest\n"},["scripts/quests/otherAreas/Go_Go_Gobmuffin.lua"]={["Path"]="scripts/quests/otherAreas/Go_Go_Gobmuffin.lua",["SHA256"]="5118881dc9d51ea11054911bbb4d8933af7f35559054095fba6bcc8fcbfd90ea",["Text"]="-----------------------------------\n-- Go! Go! Gobmuffin!\n-----------------------------------\n-- Log ID: 4, Quest ID: 69\n-- Epinolle             !pos 81.728 -33.970 66.351\n-- Spatial Displasement !pos 386.340 52.400 692.492\n-----------------------------------\nlocal riverneID = zones[xi.zone.RIVERNE_SITE_B01]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.GO_GO_GOBMUFFIN)\n\nquest.reward =\n{\n    exp     = 2000,\n    gil     = 2000,\n    keyItem = xi.keyItem.MAP_OF_CAPE_RIVERNE,\n}\n\nlocal nmBitTable =\n{\n    [riverneID.mob.SPELL_SPITTER_SPILUSPOK    ] = 0,\n    [riverneID.mob.SPELL_SPITTER_SPILUSPOK + 1] = 1,\n    [riverneID.mob.SPELL_SPITTER_SPILUSPOK + 2] = 2,\n}\n\nlocal nmStatus = function(player, mob)\n    local nmBitmask = player:getLocalVar('GobmuffinNM')\n    local bitNumber = nmBitTable[mob:getID()]\n    nmBitmask       = utils.mask.setBit(nmBitmask, bitNumber, true)\n\n    if nmBitmask == 7 then -- All 3 bits are true.\n        quest:setVar(player, 'Prog', 1)\n    else\n        player:setLocalVar('GobmuffinNM', nmBitmask) -- Resets upon zoning causing the player to need to refight the NMs\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.SHELTERING_DOUBT)\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Epinolle'] = quest:progressEvent(232),\n\n            onEventFinish =\n            {\n                [232] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Epinolle'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(234)\n                    else\n                        return quest:event(233)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [234] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.RIVERNE_SITE_B01] =\n        {\n            ['Book_Browser_Bokabraq'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        nmStatus(player, mob)\n                    end\n                end,\n            },\n\n            ['Chemical_Cook_Chemachiq'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        nmStatus(player, mob)\n                    end\n                end,\n            },\n\n            ['Spell_Spitter_Spilospok'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        nmStatus(player, mob)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [17] = function(player, csid, option, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        not GetMobByID(riverneID.mob.SPELL_SPITTER_SPILUSPOK):isSpawned() and\n                        not GetMobByID(riverneID.mob.SPELL_SPITTER_SPILUSPOK + 1):isSpawned() and\n                        not GetMobByID(riverneID.mob.SPELL_SPITTER_SPILUSPOK + 2):isSpawned()\n                    then\n                        for i = 0, 2 do\n                            SpawnMob(riverneID.mob.SPELL_SPITTER_SPILUSPOK + i):updateClaim(player)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Epinolle'] = quest:event(235):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/In_Search_of_the_Truth.lua"]={["Path"]="scripts/quests/otherAreas/In_Search_of_the_Truth.lua",["SHA256"]="d542466d62beeff4062e7bdb04d9f22e5ad6806f56c0c71c7dadecf2b70a0dde",["Text"]="-----------------------------------\n-- In Search of the Truth\n-----------------------------------\n-- Log ID: 4, Quest ID: 80\n-----------------------------------\n-- CoP Mission 3-5 Darkness Named Completed\n-----------------------------------\n-- Tavnazian Safehold           !zone 26\n-- Tressia                      !pos 87.527 -33.991 70.481\n-- Raminey                      !pos 82.396 -35.972 49.707\n-- Zadant                       !pos -10.532 -21.996 -15.71\n-- Fouagine                     !pos 25.313 -35.911 -20.944\n-- Noam                         !pos -70.17 -11.264 6.788\n-- Mengrenaux                   !pos 72.844 -34.25 63.924\n-- Chemioue                     !pos 82.041 -33.964 67.636\n-- Ondieulix                    !pos 6.775 -24.955 65.399\n-- qm1_in_search_of_truth       !pos -73.005 -11.123 11.842\n-- qm2_in_search_of_truth       !pos -80.654 -19.988 65.902\n-- qm3_in_search_of_truth       !pos -61.469 -22.007 44.123\n-- qm4_in_search_of_truth       !pos -26.099 -21.955 26.298\n-- qm5_in_search_of_truth       !pos -4.733 -22.733 23.587\n-- KI Shaded Cruse              718\n-----------------------------------\nlocal ID = zones[xi.zone.TAVNAZIAN_SAFEHOLD]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.IN_SEARCH_OF_THE_TRUTH)\n\nquest.reward =\n{\n    item = xi.item.GRAMARY_CAPE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getCurrentMission(xi.mission.log_id.COP) > xi.mission.id.cop.DARKNESS_NAMED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Tressia'] = quest:progressEvent(544, { [1] = xi.keyItem.SHADED_CRUSE }),\n\n            onEventFinish =\n            {\n                [544] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        -- First portion of quest\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            quest:getVar(player, 'Prog') == 0\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Tressia'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 30 then\n                        return quest:progressEvent(557)\n                    else\n                        return quest:event(556)\n                    end\n                end,\n            },\n\n            ['Raminey'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Option', 1) then\n                        return quest:progressEvent(549)\n                    end\n                end,\n            },\n            ['Zadant'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Option', 2) then\n                        return quest:progressEvent(551)\n                    end\n                end,\n            },\n            ['Fouagine'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Option', 3) then\n                        return quest:progressEvent(553)\n                    end\n                end,\n            },\n            ['Noam'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Option', 4) then\n                        return quest:progressEvent(555)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [549] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Option', 1)\n                end,\n\n                [551] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Option', 2)\n                end,\n\n                [553] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Option', 3)\n                end,\n\n                [555] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Option', 4)\n                end,\n\n                [557] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Option', 0)\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        -- Second portion of quest\n        -- Does not care if you talked to Mengrenaux or Chemioue. Will progress if you enter the correct order after talking to Tressia.\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            quest:getVar(player, 'Prog') == 1\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Tressia'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(565)\n                end,\n            },\n\n            ['Mengrenaux'] = quest:event(560),\n\n            ['Chemioue'] = quest:event(561),\n\n            onEventFinish =\n            {\n                [565] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    {\n        -- Third portion of quest\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            quest:getVar(player, 'Prog') == 2\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Tressia'] =\n            {\n                onTrigger = function(player, npc)\n                    local options = quest:getVar(player, 'Option')\n                    if options == 1 then\n                        return quest:progressEvent(562)\n                    elseif options == 0 then\n                        return quest:event(566)\n                    end\n                end,\n            },\n\n            -- ???'s for the trail must be checked in order.\n            ['qm1_in_search_of_truth'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not player:hasKeyItem(xi.keyItem.SHADED_CRUSE) and\n                        quest:getVar(player, 'Option') == 0\n                    then\n                        player:addKeyItem(xi.keyItem.SHADED_CRUSE)\n                        quest:setVar(player, 'Water', 1)\n                        return quest:messageSpecial(ID.text.CRUSE_ON_THE_GROUND, xi.keyItem.SHADED_CRUSE)\n                    elseif player:hasKeyItem(xi.keyItem.SHADED_CRUSE) then\n                        return quest:message(ID.text.TRAIL_OF_WATER)\n                    end\n                end,\n            },\n\n            ['qm2_in_search_of_truth'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.SHADED_CRUSE) and\n                        quest:getVar(player, 'Water') >= 1\n                    then\n                        quest:setVar(player, 'Water', 2)\n                        return quest:message(ID.text.TRAIL_OF_WATER)\n                    end\n                end,\n            },\n\n            ['qm3_in_search_of_truth'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.SHADED_CRUSE) and\n                        quest:getVar(player, 'Water') >= 2\n                    then\n                        quest:setVar(player, 'Water', 3)\n                        return quest:message(ID.text.TRAIL_OF_WATER)\n                    end\n                end,\n            },\n\n            ['qm4_in_search_of_truth'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.SHADED_CRUSE) and\n                        quest:getVar(player, 'Water') >= 3\n                    then\n                        quest:setVar(player, 'Water', 4)\n                        return quest:message(ID.text.TRAIL_OF_WATER)\n                    end\n                end,\n            },\n\n            ['qm5_in_search_of_truth'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.SHADED_CRUSE) and\n                        quest:getVar(player, 'Water') == 4\n                    then\n                        return quest:progressEvent(558, { [1] = xi.keyItem.SHADED_CRUSE })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [558] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.SHADED_CRUSE)\n                    quest:setVar(player, 'Option', 1)\n                    quest:setVar(player, 'Water', 0)\n                    player:completeQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.IN_SEARCH_OF_THE_TRUTH)\n                end,\n            },\n        },\n    },\n\n    {\n        -- Post Final Cutscene Stuff including getting the reward\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Tressia'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') >= 1 then\n                        return quest:progressEvent(562)\n                    else\n                        return quest:event(314):replaceDefault()\n                    end\n                end,\n            },\n\n            ['Ondieulix'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 2 then\n                        return quest:progressEvent(559)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [559] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 0)\n                    quest:complete(player)\n                end,\n\n                [562] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 2)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Inside_the_Belly.lua"]={["Path"]="scripts/quests/otherAreas/Inside_the_Belly.lua",["SHA256"]="722f706b95134c0d903c24a35d8563c4ccab7b15fd00ed4b76b4878dc05a4e92",["Text"]="-----------------------------------\n-- Inside the Belly\n-----------------------------------\n-- Log ID: 4, Quest ID: 26\n-- !addquest 4 26\n-- Zaldon  : !pos -11.810 -7.287 -6.742 248\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.INSIDE_THE_BELLY)\n\nquest.reward = {}\n\n-- data from http://wiki.ffxiclopedia.org/wiki/Inside_the_Belly\nlocal fishRewards =\n{\n    [xi.item.GRIMMONITE] = -- Grimmonite\n    {\n        gil = 350,\n        items =\n        {\n            { chance = 5, itemId = xi.item.GOLD_RING }, -- guessing 5%. Wiki unknown\n            { chance = 5, itemId = xi.item.MYTHRIL_RING }, -- guessing 5%. Wiki unknown\n            { chance = 5, itemId = xi.item.SILVER_RING }, -- guessing 5%. Wiki unknown\n        }\n    },\n\n    [xi.item.RYUGU_TITAN] =\n    {\n        gil = 800,\n        items =\n        {\n            { chance = 1.3, itemId = xi.item.MERCURIAL_SWORD },\n        }\n    },\n\n    [xi.item.GIANT_DONKO_1] =\n    {\n        gil = 96,\n        items =\n        {\n            { chance = 4.7, itemId = xi.item.BROKEN_HALCYON_FISHING_ROD },\n        }\n    },\n\n    [xi.item.JUNGLE_CATFISH] =\n    {\n        gil = 300,\n        items =\n        {\n            { chance = 3, itemId = xi.item.BROKEN_HUME_FISHING_ROD },\n        }\n    },\n\n    [xi.item.GIANT_CHIRAI] =\n    {\n        gil = 550,\n        items =\n        {\n            { chance = 1.2, itemId = xi.item.SPOOL_OF_TWINTHREAD },\n        }\n    },\n\n    [xi.item.CAVE_CHERAX] =\n    {\n        gil = 800,\n        items =\n        {\n            { chance = 26.2, itemId = xi.item.DWARF_PUGIL },\n        }\n    },\n\n    [xi.item.ARMORED_PISCES] =\n    {\n        gil = 475,\n        items =\n        {\n            { chance = 0.4, itemId = xi.item.STOLID_BREASTPLATE },\n        }\n    },\n\n    [xi.item.TRICORN] =\n    {\n        gil = 810,\n        items =\n        {\n            { chance = 4, itemId = xi.item.CHUNK_OF_DARKSTEEL_ORE }, -- guessing 4%. Wiki unknown\n        }\n    },\n\n    [xi.item.ZAFMLUG_BASS] =\n    {\n        gil = 15,\n        items =\n        {\n            { chance = 1.4, itemId = xi.item.BLUE_ROCK },\n        }\n    },\n\n    [xi.item.MONKE_ONKE_1] =\n    {\n        gil = 150,\n        items =\n        {\n            { chance = 10, itemId = xi.item.PINCH_OF_POISON_DUST, min = 1, max = 6 }, -- guessing 10%. Wiki unknown\n        }\n    },\n\n    [xi.item.DARK_BASS_1] =\n    {\n        gil = 10,\n        items =\n        {\n            { chance = 4.6, itemId = xi.item.GREEN_ROCK },\n        }\n    },\n\n    [xi.item.SILVER_SHARK] =\n    {\n        gil = 250,\n        title = xi.title.ACE_ANGLER,\n        items =\n        {\n            { chance = 1.4, itemId = xi.item.TRIDENT },\n        }\n    },\n\n    [xi.item.EMPEROR_FISH] =\n    {\n        gil = 300,\n        items =\n        {\n            { chance = 1, itemId = xi.item.CUIR_HIGHBOOTS }, -- guessing 1%. Wiki says 0%\n        }\n    },\n\n    [xi.item.TAKITARO] =\n    {\n        gil = 350,\n        items =\n        {\n            { chance = 2.4, itemId = xi.item.PHILOSOPHERS_STONE },\n        }\n    },\n\n    [xi.item.BLADEFISH_1] =\n    {\n        gil = 200,\n        items =\n        {\n            { chance = 11.7, itemId = xi.item.ROBBER_RIG },\n        }\n    },\n\n    [xi.item.GIGANT_SQUID] =\n    {\n        gil = 300,\n        items =\n        {\n            { chance = 2.5, itemId = xi.item.FLAME_SHIELD }, -- guessing 2.5%. Wiki unknown\n        }\n    },\n\n    [xi.item.SEA_ZOMBIE] =\n    {\n        gil = 350,\n        items =\n        {\n            { chance = 26.1, itemId = xi.item.DRILL_CALAMARY },\n        }\n    },\n\n    [xi.item.TITANICTUS] =\n    {\n        gil = 350,\n        title = xi.title.LU_SHANG_LIKE_FISHER_KING,\n        items =\n        {\n            { chance = 1.3, itemId = xi.item.ANCIENT_SWORD },\n            { chance =   5, itemId = xi.item.SEASHELL }, -- guessing 5%. Wiki unknown\n        }\n    },\n\n    [xi.item.GAVIAL_FISH] =\n    {\n        gil = 250,\n        items =\n        {\n            { chance = 4.9, itemId = xi.item.DRONE_EARRING },\n        }\n    },\n\n    [xi.item.THREE_EYED_FISH_1] =\n    {\n        gil = 250,\n        items =\n        {\n            { chance = 10, itemId = xi.item.PINCH_OF_PARALYSIS_DUST, min = 1, max = 10 }, -- guessing 10%. Wiki unknown\n        }\n    },\n\n    [xi.item.BHEFHEL_MARLIN_1] =\n    {\n        gil = 150,\n        items =\n        {\n            { chance = 14.3, itemId = xi.item.BRIGANDS_CHART },\n            { chance =  4.4, itemId = xi.item.PIRATES_CHART },\n        }\n    },\n\n    [xi.item.GUGRU_TUNA_1] =\n    {\n        gil = 50,\n        items =\n        {\n            { chance = 2.5, itemId = xi.item.TINY_TATHLUM },\n        }\n    },\n\n    [xi.item.OGRE_EEL_1] =\n    {\n        gil = 16,\n        title = xi.title.CORDON_BLEU_FISHER,\n        items =\n        {\n            { chance = 2.5, itemId = xi.item.TURQUOISE_RING },\n        }\n    },\n\n    [xi.item.TITANIC_SAWFISH] =\n    {\n        gil = 810,\n        items =\n        {\n            { chance = 0.7, itemId = xi.item.AIZENKUNITOSHI },\n        }\n    },\n\n    [xi.item.GUGRUSAURUS] =\n    {\n        gil = 880,\n        items =\n        {\n            { chance = 0.4, itemId = xi.item.SABER_SHOOT },\n        }\n    },\n\n    [xi.item.LIK] =\n    {\n        gil = 880,\n        items =\n        {\n            { chance = 0.5, itemId = xi.item.SPOOL_OF_OPAL_SILK },\n        }\n    },\n\n    [xi.item.PTERYGOTUS] =\n    {\n        gil = 390,\n        items =\n        {\n            { chance = 6.7, itemId = xi.item.LAPIS_LAZULI },\n        }\n    },\n\n    [xi.item.MOLA_MOLA] =\n    {\n        gil = 487,\n        items =\n        {\n            { chance = 1.8, itemId = xi.item.MERCURIAL_SPEAR },\n        }\n    },\n\n    [xi.item.RHINOCHIMERA_1] =\n    {\n        gil = 300,\n        items =\n        {\n            { chance = 3.2, itemId = xi.item.SOLON_TORQUE },\n        }\n    },\n\n    [xi.item.ISTAVRIT_1] =\n    {\n        gil = 50,\n        items =\n        {\n            { chance = 10, itemId = xi.item.PINCH_OF_VENOM_DUST, min = 1, max = 6 }, -- guessing 10%. Wiki unknown\n        }\n    },\n\n    [xi.item.TURNABALIGI] =\n    {\n        gil = 340,\n        items =\n        {\n            { chance =   1, itemId = xi.item.CHUNK_OF_DARK_ORE },\n            { chance = 1.4, itemId = xi.item.CHUNK_OF_ICE_ORE },\n            { chance = 1.4, itemId = xi.item.CHUNK_OF_WATER_ORE },\n        }\n    },\n\n    [xi.item.KALKANBALIGI] =\n    {\n        gil = 390,\n        items =\n        {\n            { chance = 3.3, itemId = xi.item.FLAT_SHIELD },\n        }\n    },\n\n    [xi.item.VEYDAL_WRASSE_1] =\n    {\n        gil = 225,\n        items =\n        {\n            { chance = 5, itemId = xi.item.NEBIMONITE }, -- guessing 5%. Wiki unknown\n            { chance = 5, itemId = xi.item.SEASHELL }, -- guessing 5%. Wiki unknown\n        }\n    },\n\n    [xi.item.LAKERDA] =\n    {\n        gil = 51,\n        items =\n        {\n            { chance =   6, itemId = xi.item.PEARL },\n            { chance = 1.9, itemId = xi.item.BLACK_PEARL },\n        }\n    },\n\n    [xi.item.KILICBALIGI] =\n    {\n        gil = 150,\n        items =\n        {\n            { chance = 2.5, itemId = xi.item.RUSTY_GREATSWORD }, -- guessing 2.5%. Wiki unknown\n        }\n    },\n\n    [xi.item.AHTAPOT] =\n    {\n        gil = 350,\n        items =\n        {\n            { chance = 18.5, itemId = xi.item.MILDEWY_INGOT },\n            { chance = 10.2, itemId = xi.item.DECAYED_INGOT },\n        }\n    },\n\n    [xi.item.MORINABALIGI] =\n    {\n        gil = 300,\n        items =\n        {\n            { chance = 5, itemId = xi.item.CUIR_GLOVES }, -- guessing 5%. Wiki unknown\n        }\n    },\n\n    [xi.item.YAYINBALIGI] =\n    {\n        gil = 50,\n        items =\n        {\n            { chance = 5, itemId = xi.item.TELLURIC_RING }, -- guessing 5%. Wiki unknown\n        }\n    },\n\n    [xi.item.MEGALODON] =\n    {\n        gil = 532,\n        items =\n        {\n            { chance = 3, itemId = xi.item.BROKEN_MITHRAN_FISHING_ROD }, -- guessing 3%. Wiki unknown\n            { chance = 3, itemId = xi.item.MITHRAN_FISHING_ROD }, -- guessing 3%. Wiki unknown\n        }\n    },\n\n    [xi.item.MATSYA] =\n    {\n        gil = 12592,\n        items =\n        {\n            { chance = 1.2, itemId = xi.item.SHAPERS_SHAWL },\n        }\n    },\n\n    [xi.item.PIRARUCU] =\n    {\n        gil = 516,\n        items =\n        {\n            { chance =   5, itemId = xi.item.WYVERN_SKIN }, -- guessing 5%. Wiki unknown\n            { chance = 2.5, itemId = xi.item.PEISTE_SKIN }, -- guessing 2.5%. Wiki unknown\n        }\n    },\n\n    [xi.item.GERROTHORAX] =\n    {\n        gil = 423,\n        items =\n        {\n            { chance = 1.2, itemId = xi.item.RISKY_PATCH },\n        }\n    },\n\n    [xi.item.GIGANT_OCTOPUS_1] =\n    {\n        gil = 119,\n        items =\n        {\n            { chance = 10, itemId = xi.item.JAR_OF_BLACK_INK, min = 1, max = 6 }, --guessing 10%. Wiki unknown\n        }\n    },\n\n    [xi.item.ABAIA] = -- Abaia\n    {\n        gil = 690,\n        items =\n        {\n            { chance =  1.5, itemId = xi.item.AURORA_BASS, min = 1, max = 1 }, -- Aurora Bass x3\n            { chance =  7.8, itemId = xi.item.AURORA_BASS, min = 2, max = 2 }, -- Aurora Bass x2\n            { chance = 12.5, itemId = xi.item.AURORA_BASS, min = 3, max = 3 }, -- Aurora Bass x1\n            { chance =  0.7, itemId = xi.item.PLUMB_BOOTS },\n        }\n    },\n\n    [xi.item.SORYU] =\n    {\n        gil = 1512,\n        items =\n        {\n            { chance = 46.8, itemId = xi.item.SORYUS_LIVER },\n        }\n    },\n\n    [xi.item.SEKIRYU] =\n    {\n        gil = 1512,\n        items =\n        {\n            { chance = 48.1, itemId = xi.item.SEKIRYUS_LIVER }, -- guessing 48.1%. Wiki unknown\n        }\n    },\n\n    [xi.item.HAKURYU] =\n    {\n        gil = 1512,\n        items =\n        {\n            { chance = 48.1, itemId = xi.item.HAKURYUS_LIVER },\n        }\n    },\n\n    [xi.item.GIANT_CATFISH_1] =\n    {\n        gil = 50,\n        title = xi.title.CORDON_BLEU_FISHER,\n        items =\n        {\n            { chance = 6.2, itemId = xi.item.EARTH_WAND },\n        }\n    },\n\n    [xi.item.DORADO_GAR] =\n    {\n        gil = 568,\n        items =\n        {\n            { chance = 5, itemId = xi.item.GOLD_INGOT, min = 1, max = 4 }, -- guessing 5%. Wiki unknown\n        }\n    },\n\n    [xi.item.CROCODILOS] =\n    {\n        gil = 1763,\n        items =\n        {\n            { chance = 2.3, itemId = xi.item.PUFFIN_RING },\n        }\n    },\n\n    [xi.item.PELAZOEA] =\n    {\n        gil = 360,\n        items =\n        {\n            { chance = 1.8, itemId = xi.item.NODDY_RING },\n        }\n    },\n\n    [xi.item.FAR_EAST_PUFFER] =\n    {\n        gil = 735,\n        items =\n        {\n            { chance = 5, itemId = xi.item.STINKY_SUBLIGAR }, -- guessing 5%. Wiki unknown\n        }\n    },\n}\n\nlocal function tradeFish(player, fishId)\n    quest:setLocalVar(player, 'fishId', fishId)\n    quest:setLocalVar(player, 'itemIdx', 0)\n\n    local rewards = fishRewards[fishId].items\n    local roll    = math.randomInt(1, 1000)\n    local sum     = 0\n\n    -- NOTE: We confirm the trade now, and not at the end of the cutscene as normal\n    --     : because the cutscene gives away whether or not the trade was successful\n    --     : or not, and it's possible for players to cheese this trade by force-dc-ing.\n    player:confirmTrade()\n\n    for idx = 1, #rewards do\n        sum = sum + (rewards[idx].chance * 10)\n\n        if roll <= sum then\n            quest:setLocalVar(player, 'itemIdx', idx)\n\n            return quest:event(166, 0, rewards[idx].itemId)\n        end\n    end\n\n    return quest:event(167)\nend\n\nlocal function giveReward(player)\n    local fishId  = quest:getLocalVar(player, 'fishId')\n    local itemIdx = quest:getLocalVar(player, 'itemIdx')\n    local reward  = fishRewards[fishId]\n\n    if itemIdx > 0 then\n        local rewardItem = reward.items[itemIdx]\n        local itemId = rewardItem.itemId\n        local itemQt = 1\n\n        if rewardItem.min ~= nil and rewardItem.max ~= nil then\n            itemQt = math.randomInt(rewardItem.min, rewardItem.max)\n        end\n\n        npcUtil.giveItem(player, { { itemId, itemQt } })\n    end\n\n    npcUtil.giveCurrency(player, 'gil', reward.gil)\n    quest:setLocalVar(player, 'fishId', 0)\n    quest:setLocalVar(player, 'itemIdx', 0)\n\n    if reward.title ~= nil then\n        player:addTitle(reward.title)\n    end\nend\n\nlocal function zaldonOnTrade(player, npc, trade)\n    for itemSlot = 0, trade:getSlotCount() - 1 do\n        local itemId = trade:getItemId(itemSlot)\n\n        if\n            fishRewards[itemId] ~= nil and\n            npcUtil.tradeHasExactly(trade, itemId)\n        then\n            return tradeFish(player, itemId)\n        end\n    end\nend\n\nlocal function zaldonOnTrigger(player, npc)\n    local fishingSkill = xi.crafting.getTotalSkill(player, xi.skill.FISHING)\n\n    local tier = 4\n\n    if fishingSkill < 40 then\n        tier = 1\n    elseif fishingSkill < 50 then\n        tier = 2\n    elseif fishingSkill < 75 then\n        tier = 3\n    end\n\n    local csTier =\n    {\n        {\n            162,\n            xi.item.GIANT_CATFISH_1,\n            xi.item.DARK_BASS_1,\n            xi.item.OGRE_EEL_1,\n            xi.item.ZAFMLUG_BASS,\n        },\n\n        {\n            163,\n            xi.item.ZAFMLUG_BASS,\n            xi.item.GIANT_DONKO_1,\n            xi.item.BHEFHEL_MARLIN_1,\n            xi.item.BLADEFISH_1,\n            xi.item.SILVER_SHARK,\n        },\n\n        {\n            164,\n            xi.item.JUNGLE_CATFISH,\n            xi.item.GAVIAL_FISH,\n            xi.item.PIRARUCU,\n            xi.item.EMPEROR_FISH,\n            xi.item.MEGALODON,\n            xi.item.MORINABALIGI,\n        },\n\n        {\n            165,\n            xi.item.PTERYGOTUS,\n            xi.item.KALKANBALIGI,\n            xi.item.TAKITARO,\n            xi.item.SEA_ZOMBIE,\n            xi.item.TITANICTUS,\n            xi.item.TURNABALIGI,\n            xi.item.CAVE_CHERAX,\n            xi.item.TRICORN,\n        },\n    }\n\n    return quest:event(unpack(csTier[tier]))\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_REAL_GIFT) == xi.questStatus.QUEST_COMPLETED and\n                xi.crafting.getTotalSkill(player, xi.skill.FISHING) >= 30 and\n                xi.settings.map.FISHING_ENABLE == true\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Zaldon'] = quest:progressEvent(161),\n\n            onEventFinish =\n            {\n                [161] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                xi.crafting.getTotalSkill(player, xi.skill.FISHING) >= 30 and\n                xi.settings.map.FISHING_ENABLE == true\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Zaldon'] =\n            {\n                onTrade = function(player, npc, trade)\n                    return zaldonOnTrade(player, npc, trade)\n                end,\n\n                onTrigger = function(player, npc)\n                    return zaldonOnTrigger(player, npc)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [166] = function(player, csid, option, npc)\n                    giveReward(player)\n\n                    quest:complete(player)\n                    player:addFame(xi.fameArea.SANDORIA, 10)\n                    player:addFame(xi.fameArea.BASTOK, 10)\n                end,\n\n                [167] = function(player, csid, option, npc)\n                    giveReward(player)\n\n                    quest:complete(player)\n                    player:addFame(xi.fameArea.SANDORIA, 10)\n                    player:addFame(xi.fameArea.BASTOK, 10)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                xi.settings.map.FISHING_ENABLE == true\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Zaldon'] =\n            {\n                onTrade = function(player, npc, trade)\n                    return zaldonOnTrade(player, npc, trade)\n                end,\n\n                onTrigger = function(player, npc)\n                    return zaldonOnTrigger(player, npc)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [166] = function(player, csid, option, npc)\n                    giveReward(player)\n                end,\n\n                [167] = function(player, csid, option, npc)\n                    giveReward(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Its_Raining_Mannequins.lua"]={["Path"]="scripts/quests/otherAreas/Its_Raining_Mannequins.lua",["SHA256"]="23a00f5eb79f043d008beb2ee60d79bfabdbb190eb6767b2000bbf86248a43af",["Text"]="-----------------------------------\n-- It's Raining Mannequins!\n-----------------------------------\n-- Log ID: 4, Quest ID: 29\n-- Fyi_Chalmwoh    : !pos -39.273 -16.000 70.126 249\n-- Ramona          : !pos 12.511 -7.287 2.939 248\n-- Cheupirudaux    : !pos -138.163 11.999 250.949 231\n-- mannequin_head  : !additem 1601\n-- mannequin_body  : !additem 1602\n-- mannequin_hands : !additem 1603\n-- mannequin_legs  : !additem 1604\n-- mannequin_feet  : !additem 1605\n-----------------------------------\nlocal mhauraID = zones[xi.zone.MHAURA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ITS_RAINING_MANNEQUINS)\n\nquest.sections =\n{\n    -- Speak to Fyi Chalmwoh at G-8 in Mhaura (in the Goldsmithing shop).\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Fyi_Chalmwoh'] = quest:progressEvent(305),\n\n            onEventFinish =\n            {\n                [305] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Now go to Selbina and talk to Ramona at H-9 in the Weaver's shop. She'll give you Key Item Ye Olde Mannequin Catalogue.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            -- Hint to go to Selbina\n            ['Fyi_Chalmwoh'] = quest:event(306),\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Ramona'] = quest:progressEvent(1103),\n            -- After this her default cs becomes 175, but we have it down as 170?\n\n            onEventFinish =\n            {\n                [1103] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.YE_OLDE_MANNEQUIN_CATALOGUE)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Now go to Northern San d'Oria and talk to Cheupirudaux at F-3 in front of the Woodworking Guild. He'll give you Key Item Mannequin Joint Diagrams.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            -- Hint to go to San d'Oria\n            ['Fyi_Chalmwoh'] = quest:event(307),\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Cheupirudaux'] = quest:progressEvent(759),\n\n            onEventFinish =\n            {\n                [759] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.MANNEQUIN_JOINT_DIAGRAMS)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    -- Now go back to Mhaura and trade all 5 pieces to Fyi Chalmwoh.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Fyi_Chalmwoh'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(308)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, {\n                            xi.item.MANNEQUIN_HEAD,\n                            xi.item.MANNEQUIN_BODY,\n                            xi.item.MANNEQUIN_HANDS,\n                            xi.item.MANNEQUIN_LEGS,\n                            xi.item.MANNEQUIN_FEET\n                        })\n                    then\n                        return quest:progressEvent(309)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [309] = function(player, csid, option, npc)\n                    player:confirmTrade()\n\n                    quest:setVar(player, 'Prog', 3)\n                    quest:setVar(player, 'Wait', GetSystemTime())\n                end,\n            },\n        },\n    },\n\n    -- You have to wait about one earth minute to get your reward.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Fyi_Chalmwoh'] =\n            {\n                onTrigger = function(player, npc)\n                    local wait = quest:getVar(player, 'Wait')\n                    if GetSystemTime() >= wait + 60 then\n                        return quest:progressEvent(311)\n                    else\n                        return quest:event(310) -- Please wait\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [311] = function(player, csid, option, npc)\n                    local race = player:getRace()\n                    local chosenMannequin = xi.item.HUME_M_MANNEQUIN + race - 1\n                    if player:getFreeSlotsCount() > 0 and not player:hasItem(chosenMannequin) then\n                        if quest:complete(player) then\n                            player:tradeComplete()\n                            local item = player:addItem({ id = chosenMannequin })\n                            if item then\n                                item:setExData({ race = race })\n                            end\n\n                            player:messageSpecial(mhauraID.text.ITEM_OBTAINED, chosenMannequin)\n                        end\n                    else\n                        player:messageSpecial(mhauraID.text.ITEM_CANNOT_BE_OBTAINED + 4, chosenMannequin)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Knocking_on_Forbidden_Doors.lua"]={["Path"]="scripts/quests/otherAreas/Knocking_on_Forbidden_Doors.lua",["SHA256"]="fe764077cd732a932535a49107adb25a3e218717f2adb7c9416237483be3c46d",["Text"]="-----------------------------------\n-- Knocking on Forbidden Doors\n-----------------------------------\n-- Log ID: 4, Quest ID: 78\n-- Enaremand       : !pos\n-- Fyi_Chalmwoh    : !pos -39.273 -16.000 70.126 249\n-- Mire Incense KI : 709\n-----------------------------------\nlocal mhauraID    = zones[xi.zone.MHAURA]\nlocal phomiunaID  = zones[xi.zone.PHOMIUNA_AQUEDUCTS]\nlocal misareauxID = zones[xi.zone.MISAREAUX_COAST]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.KNOCKING_ON_FORBIDDEN_DOORS)\n\nquest.sections =\n{\n    -- START: Talk to Enaremand (J-7) on the upper level in Tavnazian Safehold\n    -- QUEST AVAILABLE\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.BEHIND_THE_SMILE)\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Enaremand'] = quest:progressEvent(535),\n\n            onEventFinish =\n            {\n                [535] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- QUEST ACCEPTED\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Chemioue'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(536)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [536] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.PHOMIUNA_AQUEDUCTS] =\n        {\n            ['Wooden_Ladder'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npc:getID() == phomiunaID.npc.LADDER_KNOCKING\n                    then -- Find a better way to identify exactly which ladder it is in case IDs shift\n                        return quest:progressEvent(38, 27) -- Essentially chains the ladder cs with the actual quest cs\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [38] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.MISAREAUX_COAST] =\n        {\n            ['qm_mire_incense'] =\n            {\n                onTrigger = function(player, npc)\n                    --- ??? by end of river\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        not player:hasKeyItem(xi.keyItem.MIRE_INCENSE)\n                    then\n                        return quest:keyItem(xi.keyItem.MIRE_INCENSE)\n                    end\n                end,\n            },\n\n            ['qm_alsha'] =\n            {\n                onTrigger = function(player, npc)\n                    local progressVar = quest:getVar(player, 'Prog')\n                    -- First time clicking on ???\n                    if\n                        player:hasKeyItem(xi.keyItem.MIRE_INCENSE) and\n                        progressVar == 2\n                    then\n                        return quest:progressEvent(556, { [1] = xi.keyItem.MIRE_INCENSE })\n\n                    -- Second time clicking on ???\n                    elseif\n                        progressVar == 3 and\n                        not GetMobByID(misareauxID.mob.ALSHA):isSpawned()\n                    then\n                        return quest:progressEvent(557, { [1] = xi.keyItem.MIRE_INCENSE })\n\n                    -- Clicking on the ??? after killing NM\n                    elseif progressVar == 4 then\n                        return quest:progressEvent(558)\n                    end\n                end,\n            },\n\n            ['Alsha'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    -- Needs backend cpp changes to allow Alsha defeating herself to not allow credit.\n                    if optParams.isKiller then\n                        local alliance = player:getAlliance()\n\n                        for _, member in ipairs(alliance) do\n                            if member:getCharVar('Quest[4][78]Prog') == 3 then\n                                quest:setVar(player, 'Prog', 4)\n                            end\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [556] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [557] = function(player, csid, option, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 3 and\n                        npcUtil.popFromQM(player, npc, misareauxID.mob.ALSHA, { claim = true, hide = 0 })\n                    then\n                        player:messageSpecial(misareauxID.text.FOUL_STENCH_OF_DEATH)\n                    end\n                end,\n\n                [558] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                    player:delKeyItem(xi.keyItem.MIRE_INCENSE)\n                    npcUtil.giveKeyItem(player, xi.keyItem.BETTER_HUMES_AND_MANNEQUINS)\n                end,\n            },\n        },\n\n        [xi.zone.MHAURA] =\n        {\n            ['Fyi_Chalmwoh'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 5 then\n                        return quest:progressEvent(321, { [0] = 704,\n                            [1] = xi.mannequin.getMannequins(player),\n                            [2] = xi.mannequin.cost.PURCHASE,\n                            [3] = xi.mannequin.cost.TRADE,\n                            [4] = xi.mannequin.cost.POSE,\n                            [5] = player:getGil(),\n                            [6] = xi.keyItem.BETTER_HUMES_AND_MANNEQUINS })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [321] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        }\n    },\n\n    -- Quest complete\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:hasKeyItem(xi.keyItem.BETTER_HUMES_AND_MANNEQUINS)\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Fyi_Chalmwoh'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(321, { [1] = xi.mannequin.getMannequins(player),\n                        [2] = xi.mannequin.cost.PURCHASE,\n                        [3] = xi.mannequin.cost.TRADE,\n                        [4] = xi.mannequin.cost.POSE,\n                        [5] = player:getGil(),\n                        })\n                end,\n\n                onTrade = function(player, npc, trade)\n                    -- Trade exactly one mannequin without gil.  Gil taken separately.\n                    local tradedMannequin = 0\n\n                    for itemId = xi.item.HUME_M_MANNEQUIN, xi.item.GALKA_MANNEQUIN do\n                        if npcUtil.tradeHasExactly(trade, itemId) then\n                            tradedMannequin = itemId\n                            break\n                        end\n                    end\n\n                    if tradedMannequin ~= 0 then\n                        return quest:progressEvent(319, { [0] = 2,\n                            [1] = xi.mannequin.getMannequins(player), -- Player Mannequin List\n                            [2] = xi.mannequin.cost.PURCHASE,\n                            [3] = xi.mannequin.cost.TRADE,\n                            [4] = 1, -- Leaving this out gives a \"It's still in pretty good condition\" message\n                            })\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [321] = function(player, csid, option, npc)\n                    if option == 0 then\n                        -- Purchase a mannequin\n                        local richEnough = 0\n                        if player:getGil() >= xi.mannequin.cost.PURCHASE then\n                            richEnough = 1\n                        end\n\n                        player:updateEvent({ [0] = richEnough, -- Not sure if this is the legitimate use, but it works.\n                            [1] = xi.mannequin.getMannequins(player),\n                            [2] = option,\n                        })\n                    elseif\n                        option >= 11 and\n                        option <= 18\n                    then\n                        -- Pose a mannequin\n                        local race = option - 10 -- From 1 to 8, for consistency in lua\n                        player:updateEvent({ [0] = 1,\n                            [1] = xi.mannequin.getMannequins(player),\n                            [2] = option,\n                            [3] = xi.mannequin.getMannequinPose(player, race),\n                        })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [319] = function(player, csid, option, npc)\n                    -- Trade mannequin.  Option = race (1-8)\n                    if\n                        option >= 1 and\n                        option <= 8 and\n                        player:delGil(xi.mannequin.cost.TRADE)\n                    then\n                        player:confirmTrade()\n                        npcUtil.giveItem(player, xi.item.HUME_M_MANNEQUIN + option - 1)\n                        local race = ((option - 1) % 8) + 1\n                        xi.mannequin.setMannequinPose(player, race, 0)\n                    end\n                end,\n\n                [321] = function(player, csid, option, npc)\n                    -- If the transaction failed, the option is nil.\n                    if player:getFreeSlotsCount() == 0 then\n                        player:messageSpecial(mhauraID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.HUME_M_MANNEQUIN + option - 1)\n                    elseif\n                        -- Purchase the mannequin.  Option = race (1-8)\n                        option >= 1 and\n                        option <= 8 and\n                        player:delGil(xi.mannequin.cost.PURCHASE)\n                    then\n                        player:messageSpecial(mhauraID.text.ITEM_OBTAINED, xi.item.HUME_M_MANNEQUIN + option - 1)\n                        player:addItem(xi.item.HUME_M_MANNEQUIN + option - 1)\n                        local race = ((option - 1) % 8) + 1\n                        xi.mannequin.setMannequinPose(player, race, 0)\n                    elseif\n                        option >= 10 and\n                        player:delGil(xi.mannequin.cost.POSE)\n                    then\n                        -- Posing a mannequin\n                        local race = ((option - 11) % 8) + 1 -- 1 to 8 for lua consistency\n                        local pose = math.floor(option / 32)\n                        xi.mannequin.setMannequinPose(player, race, pose)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Missionary_Moblin.lua"]={["Path"]="scripts/quests/otherAreas/Missionary_Moblin.lua",["SHA256"]="f7cd77582ef1f39e350ea3e70de77791ea5fc17f469a55e201ae2dfefba64720",["Text"]="-----------------------------------\n-- Missionery Moblin\n-- Log ID: 4, Quest ID: 103\n-- Koblakiq !pos -64.851 21.834 -117.521 11\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.MISSIONARY_MOBLIN)\n\nquest.reward =\n{\n    gil = 4000,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.OLDTON_MOVALPOLOS] =\n        {\n            ['Koblakiq'] = quest:progressCutscene(7),\n\n            onEventFinish =\n            {\n                [7] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.OLDTON_MOVALPOLOS] =\n        {\n            ['Koblakiq'] =\n\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.SOILED_LETTER) then\n                        return quest:progressCutscene(9)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:event(8)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [9] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                quest:getMustZone(player)\n        end,\n\n        [xi.zone.OLDTON_MOVALPOLOS] =\n        {\n            ['Koblakiq'] = quest:event(12),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Monstrosity.lua"]={["Path"]="scripts/quests/otherAreas/Monstrosity.lua",["SHA256"]="a942eb8a3e5b2ee9a323c4078e6ecdf103814de3aa851b06b828fa2662c364a9",["Text"]="-----------------------------------\n-- Monstrosity\n-- The Suspicious NPCs and Odyssean Passages are in scripts/globals/monstrosity/city.lua. The quest's\n-- priority events win over them until it is complete.\n-----------------------------------\n-- Log ID: 4, Quest ID: 34\n-- Suspicious Hume     : !pos -491.817 24.988 -618.552 109\n-- Suspicious Elvaan   : !pos 82.217 -0.199 42.682 231\n-- Suspicious Galka    : !pos 81.610 8.499 -229.065 236\n-- Suspicious Tarutaru : !pos 221.286 -12.000 225.311 240\n-- Rabbit Hide         : !additem 856\n-- Lizard Tail         : !additem 926\n-- Two-leaf Mandy Bud  : !additem 4368\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.MONSTROSITY)\n\nquest.reward = {}\n\nlocal tradeItems =\n{\n    { xi.item.LIZARD_TAIL,             xi.monstrositySpecies.LIZARD     },\n    { xi.item.RABBIT_HIDE,             xi.monstrositySpecies.RABBIT     },\n    { xi.item.TWO_LEAF_MANDRAGORA_BUD, xi.monstrositySpecies.MANDRAGORA },\n}\n\nlocal suspiciousCityNpc =\n{\n    onTrade = function(player, npc, trade)\n        if player:hasKeyItem(xi.keyItem.RING_OF_SUPERNAL_DISJUNCTION) then\n            return\n        end\n\n        for _, entry in ipairs(tradeItems) do\n            local itemId = entry[1]\n            if npcUtil.tradeMatches(trade, { { itemId, 1 } }) then\n                player:setLocalVar('MONSTROSITY_UNLOCK', entry[2])\n                return quest:progressEvent(xi.monstrosity.cityEvents[player:getZoneID()] + xi.monstrosity.cityEvent.TRADE, itemId)\n            end\n        end\n    end,\n\n    onTrigger = function(player, npc)\n        local baseEvent = xi.monstrosity.cityEvents[player:getZoneID()]\n\n        if not player:hasKeyItem(xi.keyItem.RING_OF_SUPERNAL_DISJUNCTION) then\n            return quest:priorityEvent(baseEvent + xi.monstrosity.cityEvent.INTRO)\n        else\n            return quest:priorityEvent(baseEvent + xi.monstrosity.cityEvent.HAS_RING)\n        end\n    end,\n}\n\nlocal function tradeEventFinish(player, csid, option, npc)\n    local species = player:getLocalVar('MONSTROSITY_UNLOCK')\n    player:setLocalVar('MONSTROSITY_UNLOCK', 0)\n\n    if\n        species == 0 or\n        not player:tradeComplete()\n    then\n        return\n    end\n\n    npcUtil.giveKeyItem(player, xi.keyItem.RING_OF_SUPERNAL_DISJUNCTION)\n    player:setMonstrosityData({ monstrosityId = species, species = species })\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return xi.settings.main.ENABLE_MONSTROSITY == 1 and status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PASHHOW_MARSHLANDS] =\n        {\n            ['Suspicious_Hume'] = quest:progressEvent(40),\n\n            onEventFinish =\n            {\n                [40] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return xi.settings.main.ENABLE_MONSTROSITY == 1 and status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Suspicious_Elvaan'] = suspiciousCityNpc,\n\n            onEventFinish =\n            {\n                [883] = tradeEventFinish,\n            },\n        },\n\n        [xi.zone.PASHHOW_MARSHLANDS] =\n        {\n            ['Suspicious_Hume'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.RING_OF_SUPERNAL_DISJUNCTION) then\n                        return quest:priorityEvent(41)\n                    else\n                        return quest:priorityEvent(42)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Suspicious_Galka'] = suspiciousCityNpc,\n\n            onEventFinish =\n            {\n                [419] = tradeEventFinish,\n            },\n        },\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Suspicious_Tarutaru'] = suspiciousCityNpc,\n\n            onEventFinish =\n            {\n                [881] = tradeEventFinish,\n            },\n        },\n\n        [xi.zone.FERETORY] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 2\n            end,\n\n            onEventUpdate =\n            {\n                [2] = function(player, csid, option, npc)\n                    if option == 1 then\n                        xi.monstrosity.updateIntroEvent(player)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Moogles_in_the_Wild.lua"]={["Path"]="scripts/quests/otherAreas/Moogles_in_the_Wild.lua",["SHA256"]="54900d05bd94649062c392bacc36b70986594c7ae0f83db69fa722c2d7032b2a",["Text"]="-----------------------------------\n-- Moogles in the Wild\n-----------------------------------\n-- Log ID: 4, Quest ID: 102\n-- Moogle : (Mog House, Home Nation)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.MOOGLES_IN_THE_WILD)\n\nquest.reward =\n{\n    title = xi.title.MOGS_LOVING_MASTER,\n}\n\n-- Every Mog House zone shares one section table.\nquest.sections = {}\n\nquest.sections[1] =\n{\n    check = function(player, status, vars)\n        local bedPlacedTime = quest:getVar(player, 'bedPlacedTime')\n\n        return status == xi.questStatus.QUEST_AVAILABLE and\n            player:hasCompletedQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_MOOGLE_PICNIC) and\n            xi.moghouse.inMogHouseInHomeNation(player) and\n            player:getFameLevel(player:getNation()) >= 7 and\n            quest:getLocalVar(player, 'mustZone') == 0 and\n            quest:getLocalVar(player, 'questSeen') == 0 and\n            bedPlacedTime ~= 0 and\n            GetSystemTime() > bedPlacedTime + 60\n    end\n}\n\n---@type ZoneSection\nlocal questAvailable =\n{\n    ['Moogle'] =\n    {\n        onTrigger = function(player, npc)\n            return quest:progressEvent(30013, 0, 0, 0, 6, 0, xi.item.RAPTOR_MANTLE, xi.item.WOOL_HAT)\n        end,\n    },\n\n    onEventFinish =\n    {\n        [30013] = function(player, csid, option, npc)\n            quest:setLocalVar(player, 'questSeen', 1)\n\n            if option == 1 then\n                quest:begin(player)\n            end\n        end,\n    },\n}\n\nquest.sections[2] =\n{\n    check = function(player, status, vars)\n        return status == xi.questStatus.QUEST_ACCEPTED\n    end\n}\n\n---@type ZoneSection\nlocal questAccepted =\n{\n    ['Moogle'] =\n    {\n        onTrade = function(player, npc, trade)\n            if npcUtil.tradeMatches(trade, { { xi.item.RAPTOR_MANTLE, 1 }, { xi.item.WOOL_HAT, 1 } }) then\n                return quest:progressEvent(30015)\n            end\n        end,\n\n        onTrigger = function(player, npc)\n            local questProgress = quest:getVar(player, 'Prog')\n            local questSeen = quest:getLocalVar(player, 'questSeen')\n\n            if questSeen ~= 0 then\n                return nil\n            end\n\n            if questProgress == 0 then\n                return quest:progressEvent(30014, 0, 0, 0, 0, 0, xi.item.RAPTOR_MANTLE, xi.item.WOOL_HAT)\n            elseif\n                questProgress == 1 and\n                quest:getVar(player, 'Timer') < GetSystemTime()\n            then\n                return quest:progressEvent(30016)\n            end\n        end,\n    },\n\n    onEventFinish =\n    {\n        [30014] = function(player, csid, option, npc)\n            quest:setLocalVar(player, 'questSeen', 1)\n        end,\n\n        [30015] = function(player, csid, option, npc)\n            player:tradeComplete()\n            quest:setVar(player, 'Prog', 1)\n            quest:setVar(player, 'Timer', GetSystemTime() + 60)\n        end,\n\n        [30016] = function(player, csid, option, npc)\n            if quest:complete(player) then\n                player:changeContainerSize(xi.inv.MOGSAFE, 10)\n                player:changeContainerSize(xi.inv.MOGSAFE2, 10)\n            end\n        end,\n    },\n}\n\nfor _, zoneId in ipairs(xi.moghouse.moghouseZones) do\n    quest.sections[1][zoneId] = questAvailable\n    quest.sections[2][zoneId] = questAccepted\nend\n\nreturn quest\n"},["scripts/quests/otherAreas/Paradise_Salvation_and_Maps.lua"]={["Path"]="scripts/quests/otherAreas/Paradise_Salvation_and_Maps.lua",["SHA256"]="9a4a01f0ba708a2af6e055575070c96889621d41c42a70178d719807c5beadf6",["Text"]="-----------------------------------\n-- Paradise Salvation and Maps\n-----------------------------------\n-- Log ID: 4, Quest ID: 68\n-- Nivorajean : !pos 16.712 -22.000 12.552\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.PARADISE_SALVATION_AND_MAPS)\n\nquest.reward =\n{\n    exp     = 2000,\n    gil     = 2000,\n    keyItem = xi.keyItem.MAP_OF_THE_SACRARIUM,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.THE_SAVAGE)\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Nivorajean'] = quest:progressEvent(223),\n\n            onEventFinish =\n            {\n                [223] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SACRARIUM] =\n        {\n            ['Treasure_Chest' ] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Option') == 0 and\n                        not player:hasKeyItem(xi.keyItem.PIECE_OF_RIPPED_FLOORPLANS)\n                    then\n                        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.PIECE_OF_RIPPED_FLOORPLANS)\n\n                        local chestTable =\n                        {\n                            [1] = {  31.021, -2.000,   99.013 }, -- (F-5)\n                            [2] = {  89.034, -2.000,   99.248 }, -- (H-5)\n                            [3] = {  88.223, -2.000,  -36.017 }, -- (H-9)\n                            [4] = { 177.600,  8.310,  100.000 }, -- (J-6)\n                            [5] = { 179.709, -7.693,  -97.007 }, -- (J-10)\n                            [6] = { 260.391,  0.000,   21.487 }, -- (L-8)\n                            [7] = { 111.451, -2.000, -100.159 }, -- (H-11)\n                            [8] = {   8.974, -2.179, -133.075 }, -- (F-11)\n                        }\n\n                        for i = 1, #chestTable do\n                            if player:checkDistance(chestTable[i][1], chestTable[i][2], chestTable[i][3]) < 2 then\n                                quest:setVar(player, 'Option', i)\n                                break\n                            end\n                        end\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Nivorajean'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n                    local wait     = quest:getVar(player, 'Wait')\n\n                    if player:hasKeyItem(xi.keyItem.PIECE_OF_RIPPED_FLOORPLANS) then\n                        return quest:progressEvent(225, quest:getVar(player, 'Option') - 1)\n                    elseif\n                        wait ~= VanadielUniqueDay() and\n                        progress > 0\n                    then\n                        if progress == 2 then\n                            return quest:progressEvent(228) -- Correct Coordinates Selected\n                        else\n                            return quest:progressEvent(227) -- Wrong Corrdinates Selected\n                        end\n                    elseif wait == VanadielUniqueDay() then\n                        return quest:event(226) -- Wait Longer\n                    else\n                        return quest:event(224) -- Reminder\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [225] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Wait', VanadielUniqueDay())\n                    player:delKeyItem(xi.keyItem.PIECE_OF_RIPPED_FLOORPLANS)\n                    quest:setVar(player, 'Option', 0)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 2) -- Correct Coordinates Selected\n                    else\n                        quest:setVar(player, 'Prog', 1) -- Wrong Coordinates Selected\n                    end\n                end,\n\n                [227] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 0)\n                    quest:setVar(player, 'Wait', 0)\n                end,\n\n                [228] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Petals_for_Parelbriaux.lua"]={["Path"]="scripts/quests/otherAreas/Petals_for_Parelbriaux.lua",["SHA256"]="f398739f2bee42994b9f0856283fc3785767e5f4bea1d3634700bb0f407ff0aa",["Text"]="-----------------------------------\n-- Petals for Parelbriaux\n-----------------------------------\n-- Log ID: 4, Quest ID: 74\n-- Chemioue    !pos 81.728 -33.970 66.351\n-- Ondieulix   !pos 3.563 -21.912 65.983\n-- Parelbriaux !pos 114.121 41.000 42.564\n-- qm_baumesel !pos -211.481 -16.016 287.182\n-----------------------------------\nlocal lufaiseID = zones[xi.zone.LUFAISE_MEADOWS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.PETALS_FOR_PARELBRIAUX)\n\nquest.reward =\n{\n    item  = xi.item.POWERFUL_ROPE,\n    title = xi.title.PUTRID_PURVEYOR_OF_PUNGENT_PETALS,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.DARKNESS_NAMED)\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Chemioue'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(512)\n                    end\n                end,\n            },\n\n            ['Ondieulix'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(514)\n                    end\n                end,\n            },\n\n            ['Parelbriaux'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(513)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [512] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [513] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [514] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LUFAISE_MEADOWS] =\n        {\n\n            ['Baumesel'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    player:setLocalVar('NMKilled', 1)\n                end,\n            },\n\n            ['qm_baumesel'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if\n                        progress == 3 and\n                        player:getLocalVar('NMKilled') == 1\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.PARTICULARLY_POIGNANT_PETAL)\n                        return quest:progressCutscene(115)\n                    elseif\n                        progress == 3 and\n                        player:getWeather() == xi.weather.FOG and\n                        not GetMobByID(lufaiseID.mob.BAUMESEL):isSpawned()\n                    then\n                        npcUtil.popFromQM(player, npc, lufaiseID.mob.BAUMESEL, { claim = true, hide = 0 })\n                        return quest:messageSpecial(lufaiseID.text.SPINE_CHILLING_PRESENCE)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [115] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Ondieulix'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(516)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [516] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.PARTICULARLY_POIGNANT_PETAL)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"}};
